    "denial.gapRenew": "Renewing the membership",
    "denial.gapRenewWhy": "The design puts a renewal button first. Selling one is a price resolved from the catalogue, an agreement and a payment \u2014 and taking money is reserved to the owner of this build, so there is no form anywhere in this app.",
    "denial.gapDayPass": "Selling a day pass",
    "denial.gapDayPassWhy": "There is no day-pass product in this build, and a guest entry has no screen; both are a sale, which is the same wall.",
    "denial.gapWhere": "Naming the club and the plan",
    "denial.gapWhereWhy": "The design heads this screen with the plan, the club and the door. The door is here, from the zone the refusal names. The club is one more read and tells a receptionist standing in it nothing \u2014 it belongs on the denial log, which spans clubs. The plan is what the renewal button above was for, so it waits on the same thing.",
    "denial.gapPhoto": "Showing their photo",
    "denial.gapPhotoWhy": "The design confirms identity by face at 44px. There is no object store here, so no photo is held for anybody.",
