    "member.withheldHealth": "Health and biometric fields need assurance level 3, which this session does not hold. It is opened by signing in with a passkey on a hardware authenticator — enrol one on your account if you have none. Stepping up with a recovery code does not get there.",
    "field.optional": "optional",
    "newLead.title": "Add a lead",
    "newLead.heading": "New lead",
    "newLead.lead": "Name and phone are enough. Everything else can wait.",
    "newLead.needsRead": "Without it there is no duplicate check, and a lead created with no check is a duplicate in the membership, the billing and the door log afterwards \u2014 because the lead record is the one a member grows out of.",
    "newLead.name": "Name",
    "newLead.nameNeeded": "A record needs a name.",
    "newLead.phone": "Phone",
    "newLead.phoneNeeded": "Enter the full number. The duplicate check needs it to compare against.",
    "newLead.clear": "No existing record",
    "newLead.clearWhat": "Checked as you typed against members and leads. If this number already existed, that record would open instead of a second one being created.",
    "newLead.duplicate": "This number already has a record",
    "newLead.insteadOfSecond": "Open their record, or open a lead against them \u2014 either way there is one record for this person rather than two.",
    "newLead.alsoHeldBy": {
      one: "Held by {count} other record in this tenant as well.",
      other: "Held by {count} other records in this tenant as well.",
    },
    "newLead.openThatRecord": "Open that record",
    "newLead.useThatPerson": "Add a lead for them",
    "newLead.differentPerson": "Different person",
    "newLead.checkFailed": "The duplicate check did not run",
    "newLead.checkFailedWhat": "So this number has not been compared against anything. A check that could not run is not a check that passed, which is why the button is held: say it is a different person to go ahead anyway.",
    "newLead.source": "Source",
    "newLead.noSourceChosen": "Not stated",
    "newLead.noSources": "No source has been declared for this club yet, so there is nothing to choose. A source is a row somebody creates once \u2014 an open day, a campaign, a referral \u2014 and the conversion report groups by it, which is why it is not free text.",
    "newLead.sourcesRefused": "The source list is not something this session may read, so the dropdown is absent rather than empty. A lead can be opened without one.",
    "newLead.interest": "Interest",
    "newLead.interestExclusive": "Gym only is not combined with the other two: it says what somebody is not interested in as much as what they are.",
    "newLead.create": "Save lead",
    "newLead.created": "The lead is open",
    "newLead.createdWhat": "A person and a sales record against them. Nothing has been sold and no trial has started: this is somebody to call.",
    "newLead.opened": "That person already had a lead",
    "newLead.openedWhat": "So this opened theirs rather than creating a second one, which is what the duplicate check is for. The source and the interests you chose were not applied to it \u2014 the record is the one that already existed.",
    "newLead.openNew": "Open the lead",
    "newLead.needsStepUp": "Creating a person needs a stronger sign-in than this session has. The duplicate check does not, so you can see whether a record exists either way.",
    "newLead.raiseSession": "Raise this session to create records",
    "newLead.notPermitted": "Creating a person is not something this session may do. The duplicate check is, so you can still see whether a record exists.",
    "newLead.matchPathStillOpen": "If the check finds somebody, opening a lead against them is still open to you: that needs no new person.",
    "newLead.holdChecking": "Checking this number\u2026",
    "newLead.holdDuplicate": "Open the record above, add a lead for them, or say it is a different person.",
    "newLead.holdUnknown": "Say it is a different person to create the record without a check.",
    "newLead.refused": "The lead was not opened",
    "newLead.tryAgain": "Nothing was saved. Check the fields and try again.",
    "newLead.personOnly": "The person was created and the lead was not",
    "newLead.openOrphan": "Open the person that was created",
    "newLead.notYet": "What this screen does not do yet",
    "newLead.gapOwner": "Assigning the lead to somebody",
    "newLead.gapOwnerWhy": "The pipeline draws an owner on every card and this form does not set one, because the route takes a person id and this screen has no list of staff to choose from. The lead profile assigns it, and an unassigned lead is the ordinary state of one created at a desk.",
    "newLead.gapTrial": "Starting a trial",
    "newLead.gapTrialWhy": "The design's next step after a lead is a seven-day trial, and nothing in this build marks a product as a trial \u2014 so there is no product to start one against. It is the first thing the trial slice has to decide.",
    "newLead.gapAtomic": "One command for the person and the lead",
    "newLead.gapAtomicWhy": "Two writes, and nothing makes them atomic from a browser: a person can exist with no lead. That window is reported rather than hidden, with a link to the person, and closing it needs a route that does both in one transaction.",
    "newLead.gapEmail": "An email address",
    "newLead.gapEmailWhy": "The canvas asks for a name and a phone number and says everything else can wait. An email is a second contact point the lead profile can add, and a field the design leaves out is a field that would make this screen slower at the one moment it is used.",
