    "walkIn.detectionNote": "Detection runs on the phone number as it is typed, before anything is saved. It is an exact match on the stored form of the number, so a mistyped digit finds nothing \u2014 preventing the duplicate costs one screen, and the merge exists because prevention is never perfect.",
    "walkIn.notYet": "What this screen does not do yet",
    "walkIn.gapSale": "Selling the membership",
    "walkIn.gapSaleWhy": "The design puts a sale sheet after this block. Selling is a price resolved from the catalogue, an agreement against a published contract version, a recorded signature and an activation \u2014 a flow rather than a field, and it has a screen of its own.",
    "walkIn.gapEmergency": "An emergency contact",
    "walkIn.gapEmergencyWhy": "It is a second person and a relationship between them, and the five relationship kinds this build records do not include one. Recording it as a household member would be a different fact under that name.",
    "walkIn.gapWaiver": "The waiver",
    "walkIn.gapWaiverWhy": "A waiver is a consent record against a published document version. Consent can be recorded here and there is no waiver document to record it against, so a tick box would be a consent to nothing.",
    "walkIn.gapEmailCheck": "Checking the email for a duplicate",
    "walkIn.gapEmailCheckWhy": "The read takes a kind and would answer about an email too. The design checks the phone, so that is what this screen checks; a second channel it does not draw would change what the screen says.",
