    "reports.title": "Reports",
    "reports.heading": "Reports, and the gate in front of an export",
    "reports.lead": "Each report is listed when this session can open it. A report you cannot open is absent rather than locked, because a greyed row is a promise that something could be unlocked.",
    "reports.rolesLabel": "Roles",
    "reports.gateUnreachable": "The permission service did not answer, so this page cannot say which reports you may open. That is a fault here, not a limit on your access \u2014 try again.",
    "reports.noneOpen": "No report here is open to this session. That is about your own access \u2014 the section below is about what this build cannot report at all.",
