    "rota.withdrawReason": "Why take it back",
    "rota.withdrawSubmit": "Withdraw",
    "rota.withdrawWhat": "A rota window is withdrawn, never deleted: what it said and who took it back both stay answerable, because that is the question somebody asks after a member was turned away.",
    "rota.exceptionsScope": "A dated absence. A weekly working pattern is written elsewhere and is not withdrawn here.",
    "rota.whichWeek": "Which week",
    "rota.previousWeek": "Previous week",
    "rota.thisWeek": "This week",
    "rota.nextWeek": "Next week",
