    "rota.site": "Club",
    "rota.timezone": "Times are this resource's own:",
    "rota.weekOf": "Week of {first}",
    "rota.hoursBooked": "{booked} of {open} available hours booked",
    "rota.hoursBookedNoRota": "{booked} hours booked, against no rota",
    "rota.gridTitle": "The week",
    "rota.legend": "What a cell means",
    "rota.cellClosed": "Not working",
    "rota.cellOpen": "Available, unbooked",
    "rota.cellException": "Exception",
    "rota.cellBooked": "Booked",
    "rota.markBooked": "Booked",
    "rota.markOff": "Off",
    "rota.cellConflict": "Booked, and the rota refuses it",
    "rota.conflictsTitle": "Bookings the rota now refuses",
    "rota.noConflicts": "Every booking this week sits inside the rota.",
    "rota.conflictLead": "Reducing availability never deletes a booking \u2014 the member on the other end has already been told a time. Each of these is for somebody to resolve.",
    "rota.noRotaTitle": "Nobody has written a rota for this resource",
    "rota.noRotaBody": "A room, a court and a bike have no rota in any meaningful sense, and on the day a gym opens nobody has one \u2014 so this is not \u201cnever available\u201d, it is \u201cunconstrained\u201d. Open hours read as no figure rather than as zero, and anything may be scheduled against it. A coach with no rota is the same, which is usually worth fixing.",
    "rota.nothingToDraw": "This resource has no rota rows and no bookings in this week, so there is no grid to draw. The hours below are still the honest answer.",
    "rota.reasonMasked": "Reason withheld",
    "rota.reasonMaskedWhy": "A time-off window states why somebody is away, which is the one place in a rota that free text goes \u2014 and where a health fact goes in practice. Reading it needs the permission that could have written it. The exception itself is never hidden: a grid that dropped it would be the rota lying about who is working.",
    "rota.gapsTitle": "What this grid does not do",
    "rota.gapKindLabel": "Class or personal training",
    "rota.gapKind": "Nothing in this build distinguishes a class from a personal-training session, so a booked hour is one state where the design draws two. A session comes from a template, and a template is a service and a place.",
    "rota.gapExceptionLabel": "Add an exception",
    "rota.gapException": "The design puts a button here and the server would accept it: setting working hours, breaks and time off is the one scheduling write that is routine rather than stepped-up, because a rota edited by the people who run the floor is a rota that stays right. The form is not built \u2014 it is the next piece of work on this screen, not a refusal.",
    "rota.gapHourLabel": "The grid is hourly",
    "rota.gapHour": "A cell is an hour, so a booking from 17:30 marks both 17:00 and 18:00, and the hours above are rounded to the nearest hour \u2014 which is immaterial across a week and not below one, where a half-hour booking reads as no hours beside a cell that is visibly booked. The exact minutes are on the route. The grid is for scanning; the figures are for comparing.",
    "rota.openInSchedule": "Open in the schedule",
    "rota.pickResourceInLink": "This session may read a rota and not list the resources, so open it from a link that names one.",
    "rota.noResources": "This club has no staff resources, so there is no rota to read.",
    "rota.refusedWhy": "This screen needs scheduling.schedule.read.",
    "attendanceReport.heading": "Attendance",
    "attendanceReport.title": "Visits by hour",
    "attendanceReport.chartTitle": "Visits by hour",
    "attendanceReport.timezone": "Hours are this club's own:",
    "attendanceReport.site": "Club",
