    "attendanceReport.ofThePeak": "{percent}% of the busiest hour",
    "attendanceReport.overWeeks": {
      one: "over {count} week",
      other: "over {count} weeks",
    },
    "attendanceReport.nobodyCame": "Nobody came in during this window",
    "attendanceReport.nobodyCameAtAll": "No entry was recorded at this club on these days. That is a club that was shut or a reader nothing is wired to \u2014 not a club that was quiet, which is why no hour is marked as the quietest.",
    "attendanceReport.conclusion": "**{from}\u2013{to} is the busiest window, at {peak} entries in its busiest hour.** {quiet} is the quietest hour that sees anybody, running at {percent}% of the peak.",
    "attendanceReport.anotherPeak": {
      one: "{hours} is in the same tier and sits outside that window, so there is more than one peak in the day.",
      other: "{hours} are in the same tier and sit outside that window, so there is more than one peak in the day.",
    },
    "attendanceReport.notCapacity": "Every share here is a share of the busiest hour, never of a zone's capacity. The design writes \u201c94% of floor capacity\u201d and this build will not: entries in an hour are arrivals rather than people inside at a moment, and occupancy derived from access events is advisory unless a zone reads both directions \u2014 so a percentage of capacity taken from arrivals would be a confident wrong answer in the place a manager decides whether to add a class.",
    "attendanceReport.noOpeningHours": "Nothing in this build records when a club is open, so all twenty-four hours are drawn and the quietest hour is the quietest one that saw anybody. Its share of the peak is beside it: an hour at a few per cent of the busiest is a stray entry outside opening hours rather than a gap worth filling.",
    "attendanceReport.presentations": "Every reader at this club contributes, so a member who passes the front door and then a studio reader is two entries. Narrow to one reader for a building's own arrivals.",
    "attendanceReport.weekendNotDeclared": "No table or configuration key in this build says which days are a working week \u2014 it is Sunday to Thursday in some markets and Monday to Friday in others \u2014 so the chips name which days rather than claiming what they mean to your business, and the report refuses to choose for you.",
    "attendanceReport.refusedWhy": "This report needs access.zone.read.",
    "attendanceReport.pickSiteInLink": "This session may read the report and not list the clubs, so open it from a link that names one.",
    "attendanceReport.noLocation": "This tenant has no clubs yet, so there are no hours to report.",
    "attendanceReport.gapsTitle": "What this report does not do",
    "attendanceReport.gapClassFillLabel": "Class fill",
    "attendanceReport.gapClassFill": "The design's own line for this report is \u201cpeak hours, class fill, capacity planning\u201d and the canvas draws the first of the three. Average fill per class already exists on the schedule board, where a session's seats and holds are; a second chart this design does not have would be as much a deviation as a missing one.",
    "attendanceReport.gapCapacityLabel": "Capacity headroom",
    "attendanceReport.gapCapacity": "A zone's capacity is recorded and is what a presentation is refused against. It is not comparable with an arrival count, which is the refusal stated above the chart \u2014 closing it needs a concurrency figure, which needs a zone that reads both directions.",
    "attendanceReport.gapExportLabel": "Export",
    "attendanceReport.gapExport": "ADM-RPT-05 puts a tier-four gate in front of every export \u2014 a written reason recorded and visible to the tenant, then step-up authentication. Nothing in this build exports anything, and a button that produced a file without that record would be the control removed rather than the feature added.",
    "reports.coachingName": "Coaching",
    "reports.coachingWhy": "Sessions delivered, verified and unverified per coach is MOD-023's, and the Coach Workspace is not built.",
    "reports.leadsName": "Leads and conversion",
    "reports.leadsWhy": "Source effectiveness and conversion need a CRM. There is no lead, no trial and no conversion rate in this build.",
    "reports.taxName": "Tax and e-invoicing",
    "reports.taxWhy": "Submissions and rejections are recorded per invoice and nothing aggregates them into a return. There is no connector to any tax authority.",
    "reports.notBuilt": "What the design lists and this build cannot report",
    "reports.exportTitle": "Exporting is not built, and the gate in front of it is why",
    "reports.exportBody": "ADM-RPT-05 puts a tier-4 gate in front of every export of personal or financial data: a written reason recorded and visible to the tenant, an option to leave contact details out, and step-up authentication before the file is produced. Nothing here exports anything, so the gate has nothing to stand in front of. A button producing a file without that record would be the control removed rather than the feature added.",
    "revenue.title": "Revenue",
    "revenue.heading": "Revenue \u00b7 month to date",
    "revenue.scope": "All locations \u00b7 data through {date}",
    "revenue.collected": "COLLECTED",
    "revenue.invoiced": "INVOICED",
    "revenue.outstanding": "OUTSTANDING",
    "revenue.refunded": "REFUNDED",
    "revenue.vsPrevious": "vs {first} \u2013 {last}",
    "revenue.noComparison": "no figure for the same point last month",
    "revenue.positionNote": "Outstanding is what the invoices issued this month still owe as of now, so it carries no comparison: the comparable number is a balance as it stood a month ago, which this read does not reconstruct.",
    "revenue.separateFacts": "Collected and invoiced are separate columns because they are separate facts. A report showing one number labelled \u201crevenue\u201d is the reason operators cannot reconcile their own books.",
    "revenue.bySource": "By source",
    "revenue.sourcesAreNet": "A source row is net of tax and the invoiced figure above is gross. Tax is collected on somebody else\u2019s behalf and is not revenue, so the breakdown is net and the Total row is the figure it adds up to.",
    "revenue.sourceCount": {
      one: "{count} source",
      other: "{count} sources",
    },
    "revenue.sourceCol": "SOURCE",
    "revenue.amountCol": "NET",
    "revenue.changeCol": "VS LAST MONTH",
    "revenue.totalRow": "Total",
    "revenue.empty": "Nothing was invoiced this month, so there is nothing to break down.",
    "revenue.clamped": "Last month was shorter, so the comparison is clamped to the same number of days.",
    "revenue.refused": "Not permitted",
    "revenue.refusedWhy": "This report needs finance.revenue.read.",
