    "reports.sourceRetail": "Retail",
    "reports.sourceAddon": "Subscription add-ons",
    "reports.sourceEvent": "Events",
    "reports.sourceGiftCard": "Gift cards",
    "reports.sourceUnattributed": "Raised by hand",
    "reports.unattributedWhy": "An invoice line with no catalogue variant cannot be attributed to a part of the business. It is its own row rather than being dropped, so the sources add up to the invoiced total.",
    "reports.entityNotClub": "The design breaks this down by club. Money here carries a legal entity, and the hierarchy puts brands and locations under one \u2014 so several clubs under a single entity are one column.",
    "membershipReport.title": "Membership",
    "membershipReport.heading": "Membership \u00b7 month to date",
    "membershipReport.joined": "JOINED",
    "membershipReport.left": "LEFT",
    "membershipReport.net": "NET",
    "membershipReport.active": "ACTIVE",
    "membershipReport.whyTitle": "Why they left",
    "membershipReport.whyUnavailable": "A cancellation records its reason as free prose, not as a coded reason, so there is nothing to count. The design charts five named reasons from a required field on the cancellation screen; producing those from prose would mean classifying what somebody typed, and a retention report is the wrong place to guess.",
    "membershipReport.whyAlsoSensitive": "The prose is not shown here either. A reason column is where a health fact ends up in practice, and this report is behind a routine, tenant-wide permission.",
    "membershipReport.cohortTitle": "Cohort retention is not built",
    "membershipReport.cohortWhy": "Retention by joining cohort needs each membership's start and end walked month by month. The lifecycle history can answer it and nothing does yet.",
    "membershipReport.refusedWhy": "This report needs membership.record.read.",
    "wallet.title": "Wallet and credits",
    "wallet.balance": "Balance",
    "wallet.refundable": "Refundable",
    "wallet.refundableWhy": "The cash they paid in. Promotional value is spendable and never refundable, which is why the two are counted apart.",
    "wallet.expiring": "Expiring",
