    "wallet.amount": "AMOUNT",
    "wallet.none": "This member holds no wallet credit.",
    "wallet.noMovements": "The wallet is open and nothing has moved through it.",
    "wallet.originWhy": "Every entry names its origin \u2014 a cancelled class, an overpayment, a goodwill gesture \u2014 because unexplained credit is indistinguishable from an error. A lapsed entry is shown rather than dropped: \u201cwhere did my credit go\u201d is the question a member asks.",
    "wallet.noWrites": "Topping up and adding credit are both writes, and both need a stepped-up financial permission with no form in this build. A button that answered \u201cnot permitted\u201d would be worse than its absence.",
