    "staff.openWithheld": "Open this staff record — {what}",
    "staff.unanswered": "did not answer",
    "staff.catalogueIsEnglish": "A permission's name and its description are the software's own vocabulary, published in English only — they are the same two hundred strings for every tenant, written where the permission is declared. Translating them here would be a second copy that drifts from the one the server enforces.",
    "staff.working": {
      one: "{count} working",
      other: "{count} working",
    },
    "staff.onRecord": {
      one: "{count} person on record",
      other: "{count} people on record",
    },
    "staff.notApplicableNoLogin": "Not applicable: a role is held by a login and this person has none.",
    "staff.grantEverywhere": "everywhere",
    "staff.grantAt": "at {where}",
    "staff.heading": "The team, and who can still open the product",
    "staff.profileHeading": "One person's access",
    "staff.filterLabel": "Filter the team by employment",
    "staff.filterAll": "Everyone",
    "staff.state.active": "Working",
    "staff.state.suspended": "Suspended",
    "staff.state.ended": "Left",
    "staff.stillHaveAccess": {
      one: "{count} person whose employment has ended can still sign in.",
      other: "{count} people whose employment has ended can still sign in.",
    },
    "staff.stillHaveAccessWhy": "Ending employment records that somebody left; it revokes nothing, because the staff record and the login are on separate planes under separate roles. Each of these needs their role revoked and their sessions ended.",
    "staff.accessCheckRefused": "Somebody on this list has left, and whether they can still sign in is not visible to this session: that needs `identity.identity.read`. Nobody has checked rather than nothing is wrong.",
    "staff.namesWithheld": "Some names here are withheld: a legal name is an identity field, and this session has not presented a second factor.",
    "staff.nameWithheld": "This person’s name is withheld: a legal name is an identity field, and this session has not presented a second factor.",
    "staff.nameUnread": "name not read",
    "staff.tableTitle": "Staff",
