    "recovery.noSubject": "No subject — this channel carries none",
    "recovery.noTemplate": "No published template for {key}, so this stage would send nothing. A notice nobody authored is not a notice.",
    "recovery.placeholders": "Values a sender supplies:",
    "recovery.serviceMessage": "This is the published template for the stage, and it is shown as authored rather than rendered — the values below are a sender’s to supply and this build has no payment link to supply one of them. Sent in the member’s chosen language, which is a different published template rather than a translation of this one — there is no fallback chain, so a locale with no template is refused rather than answered in another language. **The category above is what makes this a service message**: only `coaching` and `marketing` may be muted by a recipient's preference, by a CHECK on `ntf_preferences` rather than by convention, so a member who has withdrawn marketing consent still receives this. The distinction is enforced by the system rather than left to the sender.",
    "recovery.notYet": "What this screen cannot do",
    "recovery.sendTitle": "Send the links",
    "recovery.sendWhy": "Nothing in this build sends. MOD-013 authors a notification and records what a dispatcher reported; no provider, no SMTP and no outbound request exists, so every message sits at `requested`. The design's batch button has no writer behind it, and its row checkboxes select for an action that does not exist — so neither is drawn.",
    "recovery.linkTitle": "The payment link",
    "recovery.linkWhy": "`veyro.link/p/8k2m` is a single-use, member-specific URL and no table in this build holds one. That is why the preview shows the template's own placeholder rather than an address: a made-up link in a message preview would read as a link that works.",
    "recovery.cardTitle": "The card",
    "recovery.cardWhy": "There is no card brand and no last four anywhere in this build. Paragraph 1597 keeps card data out of Veyro, so `payment_method_ref` is a token held by the provider and the instrument's kind is the whole of what a row can say.",
    "recovery.consentTitle": "Who has withdrawn marketing consent",
    "recovery.consentWhy": "The design counts them. This page does not: the count needs a consent read per payer, which is a request per row, and `privacy.consent.read` is a separate permission from the one this screen is behind. The rule the count illustrates is rendered above instead, from the template's own category, because that rule is the part a sender acts on.",
