    "invoice.noEditTitle": "No edit, at any permission",
    "invoice.noEditWhy": "That is the design's decision and this schema's property at once: the five ledger tables are insert-only for both runtime roles, so there is nothing to edit with. It is the reason the timeline can be trusted.",
