    "tasks.queueUnnamed": "Queue",
    "tasks.separateFromException": "A task born from an exception links back to it, and completing the task does not resolve the exception. The work and the record of the work are separate, which is why the Command Center count does not drop when somebody ticks a box here.",
    "tasks.sourceAlwaysNamed": "Three sources: assigned by a person, generated by an automation, or suggested by Veyro. The source is always named — a task nobody can account for gets ignored.",
    "tasks.bulkHeading": "Complete several at once",
