    "tasks.bulkFailed": "Nothing was marked complete.",
    "tasks.bulkSelect": "Select for bulk completion",
    "tasks.gaps": "What these screens do not do",
    "tasks.gapAssignedBy": "The design’s meta line names who assigned a task — “Assigned by Rania”. Nothing records that: a task carries an assignee and no assigner, so re-pointing one is unattributed. “Who has what” is answerable here and “who gave it to them” is not.",
    "tasks.gapBatchMessage": "“Send 6 payment links” needs a messaging provider. MOD-013 authors a message, claims it and settles it, and sends nothing — so a button here would report work that did not happen.",
    "tasks.gapReopen": "The design offers Reopen on a resolved item. A reopening is a new case citing this one, and its reference is the organization’s own — nothing in this build mints one, and a form asking a reader to type a case number would be asking them to do the product’s job.",
    "tasks.gapSideSheet": "The design draws this as a side sheet over the Command Center, closing back to the row it opened from. The Command Center’s queue here is computed live from collections, staffing and the doors rather than filed as cases, so no row opens into this and it is a page of its own.",
    "tasks.gapUndo": "The design puts a 30-second undo on a resolution. A resolution here is forward-only by trigger, so there is nothing to undo with — which is also what makes the resolved list a record rather than a state.",
    "tasks.gapScope": "The design scopes an exception to the reader’s own club. Every permission check in this build resolves at the organization, so a club manager sees every queue.",
    "tasks.gapAffectedNames": "The design prints a reason and an amount against each record — “Card expired · 55.00” — and nothing relates an affected record to the charge it is about. The name beside each one is composed through the permission that guards a member’s record, so it is withheld where that permission is.",
