    "leads.mineNeedsAPerson": "Your sign-in is not linked to a person, so it owns no leads. Staff hold permissions and do not have to be anybody in particular, so this is ordinary rather than an error.",
    "leads.refused": "You do not hold the permission that sees leads.",
    "leads.ageCarriesColour": "Age is the column that matters here: a lead’s value decays by the hour, so it is the one that carries a mark. The list is ordered oldest contact first.",
    "leads.nameIsElsewhere": "A lead is a person with a sales stage on them, so the name, the number and the email come from the member record and are masked by its rules rather than this screen’s.",
    "leads.gapSuggestion": "The design draws an AI suggestion with its evidence — “she asked about the 19:00 spin class twice” — and the text needs a model nobody here has an account with. The permission for it exists and needs a hardware sign-in.",
    "leads.gapSuggestionLabel": "The suggested message",
    "leads.gapConversion": "The design draws a conversion rate and a trend — “31% converted over 30 days, up 4 points”. A trial is expressible now and nothing counts a conversion: the figure is leads that joined over leads created in a window, which needs a date range this read does not take and a definition of which window a conversion falls in.",
    "leads.gapConversionLabel": "The conversion rate",
    "leads.gaps": "What this screen does not do yet",
    "leads.boardLabel": "The pipeline, by stage",
    "leads.namesWithheld": "Every name here is withheld: a lead’s name is an identity field and this session cannot read one. The pipeline, the source and the age are this screen’s own and are not.",
