    "lead.summaryWithheld": "Withheld: a touchpoint's prose is where a health fact goes in practice, so it is readable only by somebody who could have written one.",
    "lead.gapTrial": "The design draws a trial clock, four visits, four classes and an engagement reading. A trial is an active membership on a trial product and nothing in this build marks one, so none of the four can be computed.",
    "lead.gapTrialLabel": "The trial and its metrics",
