    "stepUp.needsPasskey": "يحتاج هذا الإجراء مفتاح مرور على موثِّق عتادي. لا تستطيع كلمة المرور ولا رمز الاستعادة رفع هذه الجلسة إلى ذلك المستوى.",
    "stepUp.needsPasskeyWhere": "اخرج ثم ادخل من جديد بمفتاح المرور. إن لم يكن لديك واحد بعد، فسجِّله في حسابك أولاً.",
