    "desk.nobodyBooked": "\u0644\u0627 \u0623\u062d\u062f \u0645\u062d\u062c\u0648\u0632 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u062d\u0635\u0629.",
    "desk.checkIn": "\u0633\u062c\u0651\u0644 \u0627\u0644\u062d\u0636\u0648\u0631",
    "desk.checkInNotOpenYet": "\u064a\u0641\u062a\u062d \u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0642\u0628\u0644 \u0633\u0627\u0639\u0629",
    "desk.checkInClosed": "\u0623\u063a\u0644\u0642 \u0627\u0644\u062a\u0633\u062c\u064a\u0644",
    "desk.checkInRefused": "\u0644\u0645 \u064a\u064f\u0633\u062c\u0651\u0644 \u0630\u0644\u0643.",
    "desk.checkInNotPermitted": "\u062a\u0633\u062c\u064a\u0644 \u062d\u0636\u0648\u0631 \u0634\u062e\u0635 \u0644\u064a\u0633 \u0645\u0645\u0627 \u062a\u0633\u062a\u0637\u064a\u0639\u0647 \u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629.",
    "desk.checkInTooLate": "\u0644\u0627 \u064a\u0645\u0643\u0646 \u062a\u0633\u062c\u064a\u0644 \u0647\u0630\u0627 \u0627\u0644\u062d\u062c\u0632 \u0627\u0644\u0622\u0646 \u2014 \u0623\u063a\u0644\u0642\u062a \u0627\u0644\u0646\u0627\u0641\u0630\u0629\u060c \u0623\u0648 \u062c\u0631\u0649 \u062a\u0633\u0648\u064a\u062a\u0647 \u0628\u0627\u0644\u0641\u0639\u0644. \u0644\u0627 \u064a\u0632\u0627\u0644 \u0628\u0625\u0645\u0643\u0627\u0646 \u0627\u0644\u0645\u062f\u064a\u0631 \u062a\u0633\u062c\u064a\u0644\u0647.",
