    "desk.gapRelease": "\u062a\u062d\u0631\u064a\u0631 \u0627\u0644\u0645\u0643\u0627\u0646 \u0639\u0646\u062f \u0628\u062f\u0621 \u0627\u0644\u062d\u0635\u0629",
    "desk.gapReleaseWhy": "\u064a\u0642\u0648\u0644 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0625\u0646\u0643 \u0644\u0633\u062a \u0645\u0636\u0637\u0631\u0627\u064b \u0644\u062a\u0630\u0643\u0651\u0631 \u0630\u0644\u0643. \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0646\u0633\u062e\u0629 \u0623\u0646\u062a \u0645\u0636\u0637\u0631: \u062a\u0633\u0648\u064a\u0629 \u0627\u0644\u062d\u0635\u0629 \u062a\u0642\u0631\u0631 \u0645\u0646 \u062a\u063a\u064a\u0651\u0628\u060c \u0648\u0647\u0630\u0627 \u062d\u0643\u0645 \u0648\u0644\u064a\u0633 \u0645\u0633\u062d\u0627\u064b\u060c \u0641\u0644\u0627 \u0634\u064a\u0621 \u064a\u0634\u063a\u0651\u0644\u0647\u0627 \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b \u0648\u064a\u0628\u0642\u0649 \u0627\u0644\u0645\u0643\u0627\u0646 \u0645\u062d\u062c\u0648\u0632\u0627\u064b \u062d\u062a\u0649 \u064a\u0633\u0648\u0651\u064a\u0647\u0627 \u0623\u062d\u062f.",
    "desk.gapNotify": "\u0625\u0628\u0644\u0627\u063a \u0627\u0644\u0645\u0646\u062a\u0638\u0631\u064a\u0646",
    "desk.gapNotifyWhy": "\u0644\u0627 \u0634\u064a\u0621 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0646\u0633\u062e\u0629 \u064a\u0631\u0633\u0644 \u0631\u0633\u0627\u0626\u0644. \u0627\u0644\u062a\u0631\u0642\u064a\u0629 \u062a\u062d\u062c\u0632 \u0627\u0644\u0645\u0643\u0627\u0646 \u0648\u062a\u0633\u062c\u0651\u0644 \u0623\u0646 \u0623\u062d\u062f\u0627\u064b \u0644\u0645 \u064a\u064f\u0628\u0644\u0651\u063a\u060c \u0628\u062f\u0644 \u0627\u062f\u0651\u0639\u0627\u0621 \u0625\u0631\u0633\u0627\u0644 \u0631\u0633\u0627\u0644\u0629.",
    "desk.gapScan": "\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0628\u0637\u0627\u0642\u0629",
    "desk.gapScanWhy": "\u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0647\u0646\u0627 \u064a\u0643\u062a\u0628\u0647 \u0634\u062e\u0635 \u0645\u0633\u0645\u0651\u0649 \u0641\u064a \u0648\u0642\u062a \u0645\u0639\u064a\u0651\u0646. \u0644\u0627 \u0634\u064a\u0621 \u064a\u0642\u0631\u0623 \u0628\u0648\u0627\u0628\u0629\u060c \u0641\u0627\u0644\u0633\u0637\u0631 \u0627\u0644\u0645\u064f\u0633\u062c\u0651\u0644 \u064a\u0642\u0648\u0644 \u0645\u0646 \u0633\u062c\u0651\u0644\u0647.",
