    "newLead.noSources": "لم يُعلَن أي مصدر لهذا النادي بعد، فلا شيء للاختيار منه. المصدر صف يُنشئه أحدهم مرة واحدة — يوم مفتوح، حملة، إحالة — وتقرير التحويل يجمّع حسبه، ولهذا ليس نصاً حراً.",
    "newLead.sourcesRefused": "قائمة المصادر ليست ممّا تقرأه هذه الجلسة، فالقائمة المنسدلة غائبة لا فارغة. يمكن فتح عميل محتمل بدونها.",
