    "newLead.gapOwner": "إسناد العميل المحتمل إلى أحد",
    "newLead.gapOwnerWhy": "خط الأنابيب يرسم مالكاً على كل بطاقة وهذه الاستمارة لا تُسنده، لأن المسار يأخذ معرّف شخص وهذه الشاشة لا تحمل قائمة موظفين للاختيار منها. ملف العميل المحتمل يُسنده، والعميل غير المُسند هو الحالة العادية لعميل أُنشئ على المكتب.",
    "newLead.gapTrial": "بدء تجربة",
    "newLead.gapTrialWhy": "الخطوة التالية في التصميم بعد العميل المحتمل تجربة سبعة أيام، ولا شيء في هذا البناء يعلّم منتجاً كتجربة — فلا يوجد منتج تبدأ عليه. وهو أول ما على شريحة التجربة أن تقرره.",
    "newLead.gapAtomic": "أمر واحد للشخص والعميل المحتمل",
    "newLead.gapAtomicWhy": "كتابتان، ولا شيء يجعلهما ذرّيتين من المتصفح: قد يوجد شخص بلا عميل محتمل. تلك النافذة تُبلَّغ لا تُخفى، مع رابط إلى الشخص، وإغلاقها يحتاج مساراً يفعل الاثنين في معاملة واحدة.",
    "newLead.gapEmail": "عنوان بريد",
    "newLead.gapEmailWhy": "اللوحة تطلب اسماً ورقم هاتف وتقول إن كل ما عدا ذلك يمكن أن ينتظر. البريد نقطة تواصل ثانية يضيفها ملف العميل المحتمل، والحقل الذي يتركه التصميم حقل يجعل هذه الشاشة أبطأ في اللحظة الوحيدة التي تُستخدم فيها.",
