    "walkIn.birthDate": "\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0645\u064a\u0644\u0627\u062f",
    "walkIn.birthDateWhy": "\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u0627\u064b \u0644\u064a\u0633 \u0643\u0623\u0646\u0647 \u062a\u062d\u062a \u0627\u0644\u062b\u0627\u0645\u0646\u0629 \u0639\u0634\u0631\u0629: \u062a\u0627\u0631\u064a\u062e \u0645\u064a\u0644\u0627\u062f \u063a\u064a\u0631 \u0645\u0639\u0631\u0648\u0641 \u0644\u0627 \u064a\u064f\u0639\u0627\u0645\u0644 \u0643\u0642\u0627\u0635\u0631.",
