    "walkIn.openThatRecord": "\u0627\u0641\u062a\u062d \u0630\u0644\u0643 \u0627\u0644\u0633\u062c\u0644",
    "walkIn.differentPerson": "\u0634\u062e\u0635 \u0645\u062e\u062a\u0644\u0641",
    "walkIn.checkFailed": "\u0644\u0645 \u064a\u0639\u0645\u0644 \u0641\u062d\u0635 \u0627\u0644\u062a\u0643\u0631\u0627\u0631",
    "walkIn.checkFailedWhat": "\u0644\u0630\u0627 \u0644\u0645 \u064a\u064f\u0642\u0627\u0631\u0646 \u0647\u0630\u0627 \u0627\u0644\u0631\u0642\u0645 \u0628\u0634\u064a\u0621. \u0627\u0644\u0641\u062d\u0635 \u0627\u0644\u0630\u064a \u0644\u0645 \u064a\u0639\u0645\u0644 \u0644\u064a\u0633 \u0641\u062d\u0635\u0627\u064b \u0646\u0627\u062c\u062d\u0627\u064b\u060c \u0648\u0644\u0647\u0630\u0627 \u0627\u0644\u0632\u0631 \u0645\u0639\u0644\u0651\u0642: \u0642\u0644 \u0625\u0646\u0647 \u0634\u062e\u0635 \u0645\u062e\u062a\u0644\u0641 \u0644\u0644\u0645\u062a\u0627\u0628\u0639\u0629 \u0631\u063a\u0645 \u0630\u0644\u0643.",
