    "walkIn.holdDuplicate": "\u0627\u0641\u062a\u062d \u0627\u0644\u0633\u062c\u0644 \u0623\u0639\u0644\u0627\u0647\u060c \u0623\u0648 \u0642\u0644 \u0625\u0646\u0647 \u0634\u062e\u0635 \u0645\u062e\u062a\u0644\u0641.",
    "walkIn.holdUnknown": "\u0642\u0644 \u0625\u0646\u0647 \u0634\u062e\u0635 \u0645\u062e\u062a\u0644\u0641 \u0644\u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u0633\u062c\u0644 \u062f\u0648\u0646 \u0641\u062d\u0635.",
    "walkIn.needsStepUp": "\u0625\u0646\u0634\u0627\u0621 \u0634\u062e\u0635 \u064a\u062d\u062a\u0627\u062c \u062a\u0633\u062c\u064a\u0644 \u062f\u062e\u0648\u0644 \u0623\u0642\u0648\u0649 \u0645\u0645\u0627 \u0644\u062f\u0649 \u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629. \u0641\u062d\u0635 \u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0644\u0627 \u064a\u062d\u062a\u0627\u062c\u0647\u060c \u0641\u062a\u0631\u0649 \u0648\u062c\u0648\u062f \u0633\u062c\u0644 \u0641\u064a \u0627\u0644\u062d\u0627\u0644\u062a\u064a\u0646.",
    "walkIn.refused": "\u0644\u0645 \u064a\u064f\u0646\u0634\u0623 \u0627\u0644\u0633\u062c\u0644",
    "walkIn.raiseSession": "\u0627\u0631\u0641\u0639 \u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629 \u0644\u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u0633\u062c\u0644\u0627\u062a",
    "walkIn.notPermitted": "\u0625\u0646\u0634\u0627\u0621 \u0634\u062e\u0635 \u0644\u064a\u0633 \u0645\u0645\u0627 \u062a\u0633\u062a\u0637\u064a\u0639\u0647 \u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629. \u0641\u062d\u0635 \u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0645\u0645\u0643\u0646\u060c \u0641\u064a\u0645\u0643\u0646\u0643 \u0631\u0624\u064a\u0629 \u0648\u062c\u0648\u062f \u0633\u062c\u0644 \u0645\u0646 \u0639\u062f\u0645\u0647.",
