    "walkIn.createdWhat": "\u0644\u0645 \u064a\u064f\u0628\u0639 \u0634\u064a\u0621: \u0647\u0630\u0627 \u0634\u062e\u0635 \u0645\u0639 \u0648\u0633\u064a\u0644\u0629 \u0627\u062a\u0635\u0627\u0644\u060c \u0648\u0647\u0630\u0627 \u0645\u0639\u0646\u0649 \u0627\u0644\u0627\u0633\u062a\u0642\u0637\u0627\u0628.",
    "walkIn.openNew": "\u0627\u0641\u062a\u062d \u0627\u0644\u0633\u062c\u0644",
    "walkIn.needsRead": "\u0628\u062f\u0648\u0646\u0647 \u0644\u0627 \u064a\u0648\u062c\u062f \u0641\u062d\u0635 \u062a\u0643\u0631\u0627\u0631\u060c \u0648\u0627\u0633\u062a\u0645\u0627\u0631\u0629 \u062a\u0646\u0634\u0626 \u0633\u062c\u0644\u0627\u062a \u0628\u0644\u0627 \u0641\u062d\u0635 \u0647\u064a \u0639\u0643\u0633 \u063a\u0631\u0636 \u0647\u0630\u0647 \u0627\u0644\u0634\u0627\u0634\u0629.",
    "walkIn.detectionNote": "\u064a\u0639\u0645\u0644 \u0627\u0644\u0641\u062d\u0635 \u0639\u0644\u0649 \u0631\u0642\u0645 \u0627\u0644\u0647\u0627\u062a\u0641 \u0623\u062b\u0646\u0627\u0621 \u0643\u062a\u0627\u0628\u062a\u0647\u060c \u0642\u0628\u0644 \u062d\u0641\u0638 \u0623\u064a \u0634\u064a\u0621. \u0648\u0647\u0648 \u0645\u0637\u0627\u0628\u0642\u0629 \u062a\u0627\u0645\u0629 \u0644\u0644\u0634\u0643\u0644 \u0627\u0644\u0645\u062e\u0632\u0651\u0646 \u0645\u0646 \u0627\u0644\u0631\u0642\u0645\u060c \u0641\u0631\u0642\u0645 \u0645\u0643\u062a\u0648\u0628 \u062e\u0637\u0623 \u0644\u0627 \u064a\u062c\u062f \u0634\u064a\u0626\u0627\u064b \u2014 \u0645\u0646\u0639 \u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u064a\u0643\u0644\u0641 \u0634\u0627\u0634\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0648\u0627\u0644\u062f\u0645\u062c \u0645\u0648\u062c\u0648\u062f \u0644\u0623\u0646 \u0627\u0644\u0645\u0646\u0639 \u0644\u0627 \u064a\u0643\u0648\u0646 \u0643\u0627\u0645\u0644\u0627\u064b \u0623\u0628\u062f\u0627\u064b.",
    "walkIn.notYet": "\u0645\u0627 \u0644\u0627 \u062a\u0641\u0639\u0644\u0647 \u0647\u0630\u0647 \u0627\u0644\u0634\u0627\u0634\u0629 \u0628\u0639\u062f",
    "walkIn.gapSale": "\u0628\u064a\u0639 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643",
    "walkIn.gapSaleWhy": "\u064a\u0636\u0639 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0633\u062a\u0645\u0627\u0631\u0629 \u0628\u064a\u0639 \u0628\u0639\u062f \u0647\u0630\u0627 \u0627\u0644\u0642\u0633\u0645. \u0627\u0644\u0628\u064a\u0639 \u0633\u0639\u0631 \u064a\u064f\u062d\u0633\u0645 \u0645\u0646 \u0627\u0644\u0643\u062a\u0627\u0644\u0648\u062c\u060c \u0648\u0627\u062a\u0641\u0627\u0642\u064a\u0629 \u0645\u0642\u0627\u0628\u0644 \u0646\u0633\u062e\u0629 \u0639\u0642\u062f \u0645\u0646\u0634\u0648\u0631\u0629\u060c \u0648\u062a\u0648\u0642\u064a\u0639\u0627\u064b \u0645\u0633\u062c\u0644\u0627\u064b\u060c \u0648\u062a\u0646\u0634\u064a\u0637\u0627\u064b \u2014 \u0645\u0633\u0627\u0631 \u0644\u0627 \u062d\u0642\u0644\u060c \u0648\u0644\u0647 \u0634\u0627\u0634\u0629 \u062e\u0627\u0635\u0629.",
    "walkIn.gapEmergency": "\u062c\u0647\u0629 \u0627\u062a\u0635\u0627\u0644 \u0644\u0644\u0637\u0648\u0627\u0631\u0626",
    "walkIn.gapEmergencyWhy": "\u0647\u064a \u0634\u062e\u0635 \u0622\u062e\u0631 \u0648\u0639\u0644\u0627\u0642\u0629 \u0628\u064a\u0646\u0647\u0645\u0627\u060c \u0648\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062a \u0627\u0644\u062e\u0645\u0633\u0629 \u0627\u0644\u0645\u0633\u062c\u0644\u0629 \u0647\u0646\u0627 \u0644\u0627 \u062a\u0634\u0645\u0644\u0647\u0627. \u062a\u0633\u062c\u064a\u0644\u0647\u0627 \u0643\u0641\u0631\u062f \u0623\u0633\u0631\u0629 \u0633\u064a\u0643\u0648\u0646 \u062d\u0642\u064a\u0642\u0629 \u0645\u062e\u062a\u0644\u0641\u0629 \u062a\u062d\u062a \u0630\u0644\u0643 \u0627\u0644\u0627\u0633\u0645.",
    "walkIn.gapWaiver": "\u0627\u0644\u0625\u0642\u0631\u0627\u0631",
    "walkIn.gapWaiverWhy": "\u0627\u0644\u0625\u0642\u0631\u0627\u0631 \u0633\u062c\u0644 \u0645\u0648\u0627\u0641\u0642\u0629 \u064a\u0633\u062a\u0646\u062f \u0625\u0644\u0649 \u0646\u0633\u062e\u0629 \u0645\u0633\u062a\u0646\u062f \u0645\u0646\u0634\u0648\u0631\u0629\u060c \u0648\u064a\u064f\u0633\u062c\u0651\u0644 \u0646\u064a\u0627\u0628\u0629 \u0639\u0646 \u0627\u0644\u063a\u064a\u0631 \u2014 \u0648\u0647\u0630\u0647 \u0635\u0644\u0627\u062d\u064a\u0629 \u0645\u062e\u062a\u0644\u0641\u0629 \u0648\u0623\u0642\u0648\u0649 \u0645\u0645\u0627 \u062a\u0637\u0644\u0628\u0647 \u0647\u0630\u0647 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0631\u0629\u060c \u0648\u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0633\u062a\u0646\u062f \u0625\u0642\u0631\u0627\u0631 \u0645\u0646\u0634\u0648\u0631 \u0644\u064a\u0633\u062a\u0646\u062f \u0625\u0644\u064a\u0647. \u0645\u0631\u0628\u0639 \u0627\u062e\u062a\u064a\u0627\u0631 \u0628\u0644\u0627 \u0646\u0633\u062e\u0629 \u062e\u0644\u0641\u0647 \u0633\u064a\u0643\u0648\u0646 \u0645\u0648\u0627\u0641\u0642\u0629 \u0639\u0644\u0649 \u0644\u0627 \u0634\u064a\u0621.",
    "walkIn.gapEmailCheck": "\u0641\u062d\u0635 \u0627\u0644\u0628\u0631\u064a\u062f \u0644\u0644\u062a\u0643\u0631\u0627\u0631",
    "walkIn.gapEmailCheckWhy": "\u062a\u0623\u062e\u0630 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0646\u0648\u0639\u0627\u064b \u0648\u0633\u062a\u062c\u064a\u0628 \u0639\u0646 \u0627\u0644\u0628\u0631\u064a\u062f \u0623\u064a\u0636\u0627\u064b. \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u064a\u0641\u062d\u0635 \u0627\u0644\u0647\u0627\u062a\u0641\u060c \u0641\u0647\u0630\u0627 \u0645\u0627 \u062a\u0641\u062d\u0635\u0647 \u0647\u0630\u0647 \u0627\u0644\u0634\u0627\u0634\u0629\u061b \u0642\u0646\u0627\u0629 \u062b\u0627\u0646\u064a\u0629 \u0644\u0627 \u064a\u0631\u0633\u0645\u0647\u0627 \u0633\u062a\u063a\u064a\u0631 \u0645\u0627 \u062a\u0642\u0648\u0644\u0647 \u0627\u0644\u0634\u0627\u0634\u0629.",
