    "credential.noLastFour": "\u064a\u0631\u0633\u0645 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0628\u0640\u00ab\u0628\u0637\u0627\u0642\u0629 \u00b7\u00b7\u00b7 8841\u00bb. \u0644\u0627 \u062a\u0648\u062c\u062f \u0623\u0631\u0628\u0639\u0629 \u0623\u062e\u064a\u0631\u0629 \u0647\u0646\u0627 \u0648\u0644\u0645 \u062a\u0648\u062c\u062f \u0623\u0628\u062f\u0627\u064b: \u0627\u0644\u0645\u062e\u0632\u0651\u0646 \u0628\u0635\u0645\u0629 \u0623\u062d\u0627\u062f\u064a\u0629 \u0627\u0644\u0627\u062a\u062c\u0627\u0647 \u0644\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0645\u064f\u0642\u062f\u0651\u0645\u0629\u060c \u0641\u0627\u0644\u0646\u0648\u0639 \u0648\u0627\u0644\u062d\u0627\u0644\u0629 \u0647\u0645\u0627 \u0643\u0644 \u0645\u0627 \u062a\u0633\u062a\u0637\u064a\u0639 \u0647\u0630\u0647 \u0627\u0644\u0634\u0627\u0634\u0629 \u062a\u0633\u0645\u064a\u062a\u0647.",
    "credential.noWrites": "\u0625\u0635\u062f\u0627\u0631 \u0628\u0637\u0627\u0642\u0629 \u0648\u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0639\u0646 \u0641\u0642\u062f\u0627\u0646\u0647\u0627 \u0643\u0644\u0627\u0647\u0645\u0627 \u0643\u062a\u0627\u0628\u0629 \u062e\u0644\u0641 \u0635\u0644\u0627\u062d\u064a\u0629 \u0645\u064f\u0631\u0641\u0651\u0639\u0629 \u0628\u0644\u0627 \u0646\u0645\u0648\u0630\u062c \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0628\u0646\u0627\u0621. \u0632\u0631\u0651 \u064a\u062c\u064a\u0628 \u00ab\u063a\u064a\u0631 \u0645\u0633\u0645\u0648\u062d\u00bb \u0623\u0633\u0648\u0623 \u0645\u0646 \u063a\u064a\u0627\u0628\u0647.",
