    "attendance.recent": "\u0632\u064a\u0627\u0631\u0627\u062a \u0623\u062e\u064a\u0631\u0629",
    "attendance.noReading": "\u064a\u0637\u0628\u0639 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u062c\u0645\u0644\u0629 \u062a\u062d\u062a \u0647\u0630\u0627 \u0627\u0644\u0631\u0633\u0645 \u2014 \u00ab\u062b\u0644\u0627\u062b\u0629 \u0623\u0633\u0627\u0628\u064a\u0639 \u0639\u0646\u062f \u0627\u0644\u0635\u0641\u0631\u00bb. \u0644\u0627 \u0634\u064a\u0621 \u0647\u0646\u0627 \u064a\u0646\u062a\u062c \u0648\u0627\u062d\u062f\u0629: \u0631\u0628\u0637 \u0627\u0644\u0627\u0646\u0642\u0637\u0627\u0639 \u0628\u0633\u0628\u0628\u0647 \u064a\u062d\u062a\u0627\u062c \u0648\u062d\u062f\u0629 \u062a\u0633\u062a\u062f\u0644\u0651 \u0639\u0644\u064a\u0647\u060c \u0648\u062c\u0645\u0644\u0629 \u0645\u0639\u0642\u0648\u0644\u0629 \u062a\u0643\u062a\u0628\u0647\u0627 \u0627\u0644\u0635\u0641\u062d\u0629 \u062a\u0643\u0648\u0646 \u062c\u0648\u0627\u0628\u0627\u064b \u0648\u0627\u062b\u0642\u0627\u064b \u0628\u0644\u0627 \u0633\u0646\u062f.",
    "attendance.credentialNote": "\u062a\u0633\u0645\u0651\u064a \u0627\u0644\u0632\u064a\u0627\u0631\u0629 \u0627\u0644\u0646\u0627\u062f\u064a \u0648\u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u062d\u0644\u064a \u0648\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u062f\u062e\u0648\u0644. \u0648\u0644\u0627 \u062a\u0633\u0645\u0651\u064a \u0627\u0644\u0628\u064a\u0627\u0646 \u0646\u0641\u0633\u0647 \u0623\u0628\u062f\u0627\u064b: \u0627\u0644\u0642\u064a\u0645\u0629 \u0627\u0644\u0645\u062e\u0632\u0651\u0646\u0629 \u0628\u0635\u0645\u0629 \u0623\u062d\u0627\u062f\u064a\u0629 \u0627\u0644\u0627\u062a\u062c\u0627\u0647\u060c \u0648\u0642\u0627\u0626\u0645\u0629 \u062a\u062d\u0645\u0644\u0647\u0627 \u062a\u062a\u064a\u062d \u0644\u0645\u0646 \u064a\u0645\u0644\u0643 \u0628\u0637\u0627\u0642\u0629 \u0645\u0631\u0634\u0651\u062d\u0629 \u0623\u0646 \u064a\u062a\u0623\u0643\u0651\u062f \u0644\u0645\u0646 \u0647\u064a.",
