    "cc.staffingBody": "الأقرب أولًا. {members} مقعدًا محجوزًا بينها، أي أن هناك من ينتظر حصة بلا مدرّب.",
    "cc.staffingBodyEmpty": "الأقرب أولًا. لم يحجز فيها أحد بعد، وهذا ما يجعل الآن أرخص وقت لتعيين مدرّب.",
