    "freeze.until": "\u0625\u0644\u0649",
    "freeze.reason": "\u0627\u0644\u0633\u0628\u0628",
    "freeze.reasonWhy": "\u064a\u064f\u0633\u062c\u0651\u0644 \u0639\u0644\u0649 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u0648\u064a\u0642\u0631\u0623\u0647 \u0645\u0646 \u064a\u0637\u0651\u0644\u0639 \u0639\u0644\u0649 \u062a\u0627\u0631\u064a\u062e\u0647. \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u064a\u0639\u0631\u0636 \u0642\u0627\u0626\u0645\u0629 \u0623\u0633\u0628\u0627\u0628\u061b \u0647\u0630\u0627 \u0627\u0644\u0625\u0635\u062f\u0627\u0631 \u064a\u0623\u062e\u0630 \u062c\u0645\u0644\u0629\u060c \u0644\u0623\u0646 \u0644\u0627 \u0645\u062c\u0645\u0648\u0639\u0629 \u0623\u0633\u0628\u0627\u0628 \u0645\u0639\u0644\u0646\u0629 \u0641\u064a \u0623\u064a \u0645\u0643\u0627\u0646.",
