    "freeze.window": "\u064a\u0628\u062f\u0623 \u0627\u0644\u062a\u062c\u0645\u064a\u062f \u0628\u064a\u0646 {from} \u0648 {to}",
    "freeze.windowWhy": "\u0644\u064a\u0633 \u0641\u064a \u0627\u0644\u0645\u0633\u062a\u0642\u0628\u0644: \u0644\u0627 \u0634\u064a\u0621 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0625\u0635\u062f\u0627\u0631 \u064a\u0637\u0628\u0651\u0642 \u062a\u062c\u0645\u064a\u062f\u0627\u064b \u0645\u062d\u062c\u0648\u0632\u0627\u064b \u0639\u0646\u062f \u062d\u0644\u0648\u0644 \u064a\u0648\u0645\u0647\u060c \u0648\u0648\u0627\u062d\u062f \u0644\u0627 \u064a\u0633\u0631\u064a \u0623\u0628\u062f\u0627\u064b \u0623\u0633\u0648\u0623 \u0645\u0646 \u0648\u0627\u062d\u062f \u0644\u0627 \u064a\u064f\u062d\u062c\u0632. \u0648\u0634\u0647\u0631 \u0644\u0644\u0648\u0631\u0627\u0621\u060c \u0644\u0623\u0646 \u0645\u0627 \u064a\u064f\u062a\u0641\u0642 \u0639\u0644\u064a\u0647 \u0627\u0644\u062c\u0645\u0639\u0629 \u064a\u064f\u0633\u062c\u0651\u0644 \u0627\u0644\u0627\u062b\u0646\u064a\u0646.",
    "freeze.openNow": "\u0647\u0630\u0627 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u0645\u062c\u0645\u0651\u062f. \u0627\u0644\u0633\u0645\u0627\u062d \u0623\u0639\u0644\u0627\u0647 \u064a\u062d\u0633\u0628 \u0627\u0644\u062a\u062c\u0645\u064a\u062f \u0627\u0644\u0645\u0641\u062a\u0648\u062d \u062d\u062a\u0649 \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062a\u0639\u0627\u0642\u062f\u064a\u0629\u060c \u0644\u0623\u0646\u0647 \u064a\u0646\u0641\u0642 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u062d \u0627\u0644\u0622\u0646 \u2014 \u0648\u0644\u064a\u0633 \u0627\u0644\u0623\u064a\u0627\u0645 \u0627\u0644\u062a\u064a \u0637\u0644\u0628\u0647\u0627 \u0623\u062d\u062f.",
    "freeze.whatHappens": "\u064a\u0646\u062a\u0642\u0644 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u0625\u0644\u0649 \u0645\u062c\u0645\u0651\u062f \u0648\u064a\u064f\u062d\u0641\u0638 \u0633\u0639\u0631\u0647. \u0627\u0644\u0641\u0648\u062a\u0631\u0629 \u0648\u0627\u0644\u062f\u062e\u0648\u0644 \u062d\u0627\u0644\u062a\u0627\u0646 \u0645\u0646\u0641\u0635\u0644\u062a\u0627\u0646 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0625\u0635\u062f\u0627\u0631 \u0648\u0644\u0627 \u064a\u0642\u0648\u062f\u0647\u0645\u0627 \u062c\u062f\u0648\u0644\u060c \u0641\u0644\u0627 \u0634\u064a\u0621 \u0647\u0646\u0627 \u064a\u0648\u0642\u0641 \u062f\u0641\u0639\u0629\u061b \u0648\u062a\u064f\u0645\u062f\u0651 \u0627\u0644\u0645\u062f\u0629 \u0639\u0646\u062f \u0627\u0644\u0627\u0633\u062a\u0626\u0646\u0627\u0641 \u0628\u0639\u062f\u062f \u0627\u0644\u0623\u064a\u0627\u0645 \u0627\u0644\u0645\u062c\u0645\u0651\u062f\u0629 \u0641\u0639\u0644\u0627\u064b\u060c \u0641\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u062a\u062c\u062f\u064a\u062f \u0627\u0644\u062c\u062f\u064a\u062f \u063a\u064a\u0631 \u0645\u0639\u0631\u0648\u0641 \u0628\u0639\u062f.",
