    "cancel.reasonWhy": "يُسجّل على الاشتراك ويقرأه من يطّلع على تاريخه. التصميم يعرض قائمة؛ هذا الإصدار يأخذ جملة، لأن لا مجموعة أسباب إلغاء معلنة في أي مكان.",
    "cancel.reasonHint": "انتقال، التكلفة، عدم الرضا، غير ذلك…",
