    "cancel.conflict": "تغيّر شيء — أعد التحميل وانظر مرة أخرى. الرقم أعلاه محسوب من تاريخ اليوم، فصفحة بقيت مفتوحة ليلة كاملة يُعاد تسعيرها.",
    "cancel.needsStepUp": "يتطلب ذلك تسجيل دخول أقوى.",
    "cancel.cannot": "لا يمكن إلغاء هذا الاشتراك من حالته الحالية، لا من أحد. اشتراك لم يُنشّط أبداً، أو أُلغي سابقاً، لا شيء فيه ليُلغى.",
    "cancel.stepUpFirst": "إلغاء الاشتراك يتطلب تسجيل دخول أقوى، لأنه ينهي ما يُحتسب على العضو وما يستطيع الوصول إليه. الأرقام أعلاه تُقرأ بدونه.",
    "cancel.stepUp": "سجّل الدخول بصورة أقوى",
    "cancel.notPermitted": "الإلغاء يتطلب membership.lifecycle.change، وهذا الدخول لا يحمله على أي مستوى.",
    "cancel.gapFeeLabel": "ما هي الرسوم، وما ليست",
    "cancel.gapFee": "هي تكلفة الإلغاء، وليست المبلغ المستحق. جزء المدة هو ما تكلّفه فترة الفوترة الحالية مقابل الأيام التي سيكون العضو قد استخدمها؛ وهل دُفعت تلك الفترة أم لا سؤال للفواتير أدناه، ولا يرتبط به هذا الرقم. أما بدل ترك الالتزام فهو دائماً مبلغ جديد.",
    "cancel.gapChargeLabel": "لا شيء يُحتسب هنا",
    "cancel.gapCharge": "تُفصح الرسوم وتُسجّل على الإلغاء، ولا تُصدر فاتورة ولا تُقبض دفعة — قبض المال يحتاج مزوّد مدفوعات لا يملكه هذا الإصدار. تبدأ مدة الإشعار من التاريخ أعلاه، وتُسحب الاستحقاقات التي منحها هذا الاشتراك عند انتهائها.",
    "freeze.noAllowance": "\u0647\u0630\u0627 \u0627\u0644\u0639\u0642\u062f \u0644\u0627 \u064a\u0633\u0645\u062d \u0628\u0627\u0644\u062a\u062c\u0645\u064a\u062f \u0625\u0637\u0644\u0627\u0642\u0627\u064b.",
    "freeze.badDates": "\u062a\u0627\u0631\u064a\u062e\u0627\u0646\u060c \u0627\u0644\u062b\u0627\u0646\u064a \u0641\u064a \u0627\u0644\u0623\u0648\u0644 \u0623\u0648 \u0628\u0639\u062f\u0647.",
    "freeze.startOutsideWindow": "\u064a\u0628\u062f\u0623 \u0627\u0644\u062a\u062c\u0645\u064a\u062f \u062e\u0644\u0627\u0644 \u0627\u0644\u0634\u0647\u0631 \u0627\u0644\u0633\u0627\u0628\u0642 \u0644\u0644\u064a\u0648\u0645\u060c \u0648\u0644\u064a\u0633 \u0641\u064a \u0627\u0644\u0645\u0633\u062a\u0642\u0628\u0644.",
    "freeze.tooLong": "\u0627\u0644\u062a\u062c\u0645\u064a\u062f \u0633\u0646\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0643\u062b\u0631.",
    "freeze.overAllowance": "\u0647\u0630\u0627 \u0623\u0637\u0648\u0644 \u0645\u0645\u0651\u0627 \u062a\u0628\u0642\u0651\u0649 \u0645\u0646 \u0633\u0645\u0627\u062d \u0627\u0644\u0633\u0646\u0629.",
    "freeze.stepUpFirst": "\u062a\u062c\u0645\u064a\u062f \u0627\u0634\u062a\u0631\u0627\u0643 \u064a\u062a\u0637\u0644\u0628 \u062a\u0633\u062c\u064a\u0644 \u062f\u062e\u0648\u0644 \u0623\u0642\u0648\u0649\u060c \u0644\u0623\u0646\u0647 \u064a\u063a\u064a\u0651\u0631 \u0645\u0627 \u064a\u064f\u062f\u0641\u0639 \u0648\u0645\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647. \u0627\u0644\u0633\u0645\u0627\u062d \u0623\u0639\u0644\u0627\u0647 \u064a\u064f\u0642\u0631\u0623 \u0628\u062f\u0648\u0646\u0647.",
    "freeze.stepUp": "\u062a\u0633\u062c\u064a\u0644 \u062f\u062e\u0648\u0644 \u0623\u0642\u0648\u0649",
    "freeze.notPermitted": "\u0627\u0644\u062a\u062c\u0645\u064a\u062f \u064a\u062a\u0637\u0644\u0628 membership.lifecycle.change\u060c \u0648\u0644\u0627 \u062a\u062d\u0645\u0644\u0647 \u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629 \u0628\u0623\u064a \u0645\u0633\u062a\u0648\u0649.",
    "freeze.gapsTitle": "\u0645\u0627 \u0644\u0627 \u064a\u0641\u0639\u0644\u0647 \u0647\u0630\u0627 \u0627\u0644\u0646\u0645\u0648\u0630\u062c",
    "freeze.gapOverrideLabel": "\u062a\u062c\u0627\u0648\u0632 \u0639\u0646\u062f \u0627\u0644\u062d\u062f",
    "freeze.gapOverride": "\u064a\u0642\u0648\u0644 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0625\u0646\u0647 \u0639\u0646\u062f 3 \u0645\u0646 3 \u064a\u064f\u0648\u0642\u0641 \u0627\u0644\u0625\u062c\u0631\u0627\u0621 \u0648\u064a\u064f\u0633\u0645\u0651\u0649 \u0627\u0644\u0645\u062f\u064a\u0631 \u0627\u0644\u0630\u064a \u064a\u0645\u0643\u0646\u0647 \u0627\u0644\u062a\u062c\u0627\u0648\u0632. MOD-008 \u0641\u064a\u0647 \u0645\u0648\u0627\u0641\u0642\u0627\u062a \u0628\u062d\u062f\u0648\u062f \u0648\u0641\u0635\u0644 \u0645\u0647\u0627\u0645\u060c \u0648\u0623\u064a \u0635\u0644\u0627\u062d\u064a\u0629 \u062a\u062a\u062c\u0627\u0648\u0632 \u0633\u0645\u0627\u062d \u0639\u0642\u062f\u060c \u0648\u0645\u0646 \u0644\u0627 \u064a\u062c\u0648\u0632 \u0644\u0647 \u0627\u0639\u062a\u0645\u0627\u062f \u0646\u0641\u0633\u0647\u060c \u0642\u0631\u0627\u0631\u0627\u062a \u0644\u0645 \u062a\u064f\u062a\u062e\u0630. \u0627\u0644\u062d\u062f \u064a\u0645\u0646\u0639 \u0647\u0646\u0627 \u0648\u0644\u0627 \u064a\u0633\u0645\u0651\u064a \u0623\u062d\u062f\u0627\u064b.",
    "freeze.gapUndoLabel": "\u062a\u0631\u0627\u062c\u0639 \u062e\u0644\u0627\u0644 \u062b\u0644\u0627\u062b\u064a\u0646 \u062b\u0627\u0646\u064a\u0629",
    "freeze.gapUndo": "\u064a\u062c\u0639\u0644\u0647 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0645\u0646 \u0627\u0644\u0641\u0626\u0629 2\u060c \u0642\u0627\u0628\u0644\u0627\u064b \u0644\u0644\u062a\u0631\u0627\u062c\u0639 \u062b\u0644\u0627\u062b\u064a\u0646 \u062b\u0627\u0646\u064a\u0629\u060c \u0644\u0623\u0646 \u062a\u062c\u0645\u064a\u062f\u0627\u064b \u0637\u064f\u0628\u0651\u0642 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0648 \u0627\u0644\u062e\u0637\u0623 \u0634\u0627\u0626\u0639 \u0648\u0631\u062e\u064a\u0635 \u0627\u0644\u0639\u0643\u0633. \u0644\u0627 \u0634\u064a\u0621 \u0647\u0646\u0627 \u064a\u0639\u0644\u0651\u0642 \u0625\u062c\u0631\u0627\u0621\u064b. \u0627\u0644\u0627\u0633\u062a\u0626\u0646\u0627\u0641 \u0647\u0648 \u0627\u0644\u0639\u0644\u0627\u062c \u0648\u0647\u0648 \u0641\u0648\u0631\u064a\u060c \u0648\u0647\u0630\u0627 \u0634\u064a\u0621 \u0622\u062e\u0631 \u0648\u0645\u0648\u062c\u0648\u062f \u0639\u0644\u0649 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u0623\u0639\u0644\u0627\u0647.",
    "finance.title": "المالية",
    "finance.lead": "السجل كما يقرأه المحاسب: أي الأشهر مغلقة، وما يحمله كل حساب، والأسئلة التي لم يجب عنها أحد بعد. لا يوجد قيد على هذه الصفحة ولا طريقة لسردها — فتلك القراءة تُرجع أرقام الفاتورة والدافع، وهي آمنة فقط ما دامت معرّفات القيود غير قابلة للتعداد.",
