    "finance.reopenedBecause": "أُعيد فتحها:",
    "finance.absenceMeansNeverOpened": "الشهر غير المدرج لم يُفتح قط، وهذا ليس كالمفتوح: القفل يُطبَّق لكل فترة على حدة، فالمستأجر الذي قُدِّمت دفاتره اللاحقة ليس لديه سطر لأي شهر سابق.",
    "finance.trialBalance": "ميزان المراجعة",
    "finance.perEntityPerCurrency": "لكل كيان قانوني ولكل عملة، لأن الفاتورة تُرقَّم لكل كيان ولأن القيد لا يعبر العملات. وهذا الميزان هو",
