    "finance.nothingPosted": "دليل الحسابات موجود ولم يُقيَّد عليه شيء. هذه حالة عادية لمستأجر في طور الإعداد: تُصدَر الفاتورة ويُتخطّى القيد مع ذكر السبب بدل رفضه.",
