    "finance.balanceUnreadable": "تعذّرت قراءة هذا الكيان مع هذه العملة معًا. ميزان المراجعة موجود لكل ثنائية، فالرابط الذي يسمّي ثنائية بلا ميزان لا شيء لديه ليعرضه.",
