    "finance.total": "الإجمالي",
    "finance.balancedByConstruction": "كل قيد متوازن بقيد تفرضه قاعدة البيانات، فهذان الإجماليان متساويان بحكم البناء. الفرق ليس مسألة تقريب.",
    "finance.cases": "أسئلة بلا إجابة",
