    "cash.conflict": "\u0647\u0630\u0627 \u0627\u0644\u062f\u0631\u062c \u0623\u064f\u063a\u0644\u0642 \u0628\u0627\u0644\u0641\u0639\u0644 \u2014 \u0623\u0639\u062f \u0627\u0644\u062a\u062d\u0645\u064a\u0644 \u0648\u0627\u0646\u0638\u0631 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.",
