    "cash.needsSuspense": "\u0644\u0627 \u064a\u0648\u062c\u062f \u062d\u0633\u0627\u0628 \u062a\u0639\u0644\u064a\u0642 \u0644\u0647\u0630\u0647 \u0627\u0644\u0645\u0646\u0634\u0623\u0629\u060c \u0648\u0644\u0627 \u0645\u0643\u0627\u0646 \u064a\u064f\u0642\u064a\u0651\u062f \u0641\u064a\u0647 \u0627\u0644\u0641\u0631\u0642. \u0623\u0636\u0641 \u0648\u0627\u062d\u062f\u0627\u064b \u0625\u0644\u0649 \u0634\u062c\u0631\u0629 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0623\u0648\u0644\u0627\u064b.",
    "cash.varianceOf": "\u0641\u0631\u0642",
    "cash.reasonGiven": "\u0627\u0644\u0633\u0628\u0628",
    "cash.refusedWhy": "\u0631\u0624\u064a\u0629 \u0627\u0644\u0623\u062f\u0631\u0627\u062c \u062a\u062a\u0637\u0644\u0628 finance.cash.session\u060c \u0648\u0647\u064a \u0627\u0644\u0635\u0644\u0627\u062d\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0641\u062a\u062d \u0627\u0644\u062f\u0631\u062c \u0648\u062a\u063a\u0644\u0642\u0647.",
    "cash.gapsTitle": "\u0645\u0627 \u0644\u0627 \u062a\u0641\u0639\u0644\u0647 \u0647\u0630\u0647 \u0627\u0644\u0634\u0627\u0634\u0629",
    "cash.gapThresholdLabel": "\u062d\u062f \u062a\u0633\u0627\u0645\u062d",
    "cash.gapThreshold": "\u064a\u0631\u0628\u0637 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0628\u062d\u062f 2.00 \u062f\u064a\u0646\u0627\u0631. \u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u062b\u0644\u0647 \u0647\u0646\u0627\u060c \u0628\u0642\u0631\u0627\u0631 \u0645\u0639\u0644\u0646 \u2014 \u062d\u062f \u0627\u0644\u062a\u0633\u0627\u0645\u062d \u0642\u0631\u0627\u0631 \u062a\u062c\u0627\u0631\u064a \u0644\u0645 \u062a\u0646\u0635\u0651 \u0639\u0644\u064a\u0647 \u0627\u0644\u0645\u0635\u0627\u062f\u0631 \u2014 \u0641\u064a\u0633\u0631\u064a \u0627\u0644\u062d\u062f \u0627\u0644\u0623\u062f\u0646\u0649 \u0628\u062f\u0644\u0627\u064b \u0645\u0646\u0647 \u0648\u064a\u062d\u062a\u0627\u062c \u0643\u0644 \u0641\u0631\u0642 \u0625\u0644\u0649 \u062c\u0645\u0644\u0629\u060c \u0648\u0647\u0630\u0627 \u0623\u0634\u062f \u0648\u0644\u064a\u0633 \u0623\u062e\u0641.",
    "cash.gapCosignLabel": "\u062a\u0648\u0642\u064a\u0639 \u062b\u0627\u0646\u064d",
    "cash.gapCosign": "\u064a\u0636\u0639 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0634\u062e\u0635\u0627\u064b \u062b\u0627\u0646\u064a\u0627\u064b \u064a\u0648\u0642\u0651\u0639 \u0639\u0644\u0649 \u062f\u0631\u062c \u0646\u0627\u0642\u0635. \u0644\u0627 \u0634\u064a\u0621 \u0647\u0646\u0627 \u064a\u0633\u062c\u0651\u0644 \u0630\u0644\u0643: MOD-008 \u0641\u064a\u0647 \u0645\u0648\u0627\u0641\u0642\u0627\u062a \u0628\u062d\u062f\u0648\u062f \u0648\u0641\u0635\u0644 \u0645\u0647\u0627\u0645\u060c \u0648\u0623\u064a \u0635\u0644\u0627\u062d\u064a\u0629 \u062a\u0648\u0627\u0641\u0642 \u0639\u0644\u0649 \u062f\u0631\u062c\u060c \u0648\u0641\u0648\u0642 \u0623\u064a \u0645\u0628\u0644\u063a\u060c \u0648\u0645\u0646 \u0644\u0627 \u064a\u062c\u0648\u0632 \u0644\u0647 \u0627\u0639\u062a\u0645\u0627\u062f \u0646\u0641\u0633\u0647 \u2014 \u0643\u0644\u0647\u0627 \u0642\u0631\u0627\u0631\u0627\u062a \u0644\u0645 \u062a\u064f\u062a\u062e\u0630. \u0632\u0631\u0651 \u0644\u0627 \u064a\u0633\u062c\u0651\u0644 \u0634\u062e\u0635\u0627\u064b \u062b\u0627\u0646\u064a\u0627\u064b \u0623\u0633\u0648\u0623 \u0645\u0646 \u063a\u064a\u0627\u0628\u0647.",
    "cash.gapSpanLabel": "\u0627\u0644\u062f\u0631\u062c \u0648\u0644\u064a\u0633 \u0627\u0644\u0648\u0631\u062f\u064a\u0629",
    "cash.gapEntryLabel": "\u0627\u0644\u0642\u064a\u062f",
    "cash.gapWhoLabel": "\u0648\u0631\u062f\u064a\u0629 \u0645\u0646",
    "cash.gapWho": "\u064a\u0636\u0639 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0627\u0633\u0645 \u0627\u0644\u0634\u062e\u0635 \u0641\u064a \u0627\u0644\u0639\u0646\u0648\u0627\u0646. \u0627\u0644\u0627\u0633\u0645 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a \u062d\u0642\u0644 \u0645\u0646 \u0641\u0626\u0629 \u0627\u0644\u0647\u0648\u064a\u0629\u060c \u0641\u062c\u0644\u0633\u0629 \u0639\u0627\u062f\u064a\u0629 \u2014 \u0648\u0647\u064a \u0645\u0633\u062a\u0648\u0649 \u0645\u0648\u0638\u0641 \u0627\u0644\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0641\u0639\u0644\u0627\u064b \u2014 \u062a\u0642\u0631\u0623\u0647 \u0645\u062d\u062c\u0648\u0628\u0627\u064b. \u0627\u0633\u0645 \u0627\u0644\u062f\u0631\u062c \u0647\u0648 \u062a\u0633\u0645\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0623\u062c\u0631 \u0644\u0647 \u0648\u0647\u0648 \u0635\u062d\u064a\u062d \u062f\u0627\u0626\u0645\u0627\u064b\u061b \u0648\u064a\u0638\u0647\u0631 \u0627\u0644\u0627\u0633\u0645 \u0628\u062f\u0644\u0627\u064b \u0645\u0646\u0647 \u0644\u0645\u0646 \u064a\u062d\u0642 \u0644\u0647 \u0631\u0624\u064a\u062a\u0647.",
    "cash.gapSpan": "\u0631\u0635\u064a\u062f \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0645\u0627 \u062f\u062e\u0644 \u0648\u0645\u0627 \u062e\u0631\u062c \u0647\u064a \u0642\u064a\u0648\u062f \u062d\u0633\u0627\u0628 \u0647\u0630\u0627 \u0627\u0644\u062f\u0631\u062c \u0646\u0641\u0633\u0647\u060c \u0648\u0645\u062c\u0645\u0648\u0639\u0647\u0627 \u0647\u0648 \u0627\u0644\u0645\u0628\u0644\u063a \u0627\u0644\u0645\u062a\u0648\u0642\u0651\u0639. \u0645\u0627 \u0644\u0645 \u062a\u0648\u062f\u0639\u0647 \u0648\u0631\u062f\u064a\u0629 \u0633\u0627\u0628\u0642\u0629 \u0644\u0627 \u064a\u0632\u0627\u0644 \u0641\u064a \u0627\u0644\u062f\u0631\u062c \u0648\u0644\u0627 \u064a\u0632\u0627\u0644 \u0645\u0639\u062f\u0648\u062f\u0627\u064b \u0647\u0646\u0627.",
    "cash.entryNote": "\u0627\u0644\u0642\u064a\u062f \u0647\u0648 \u0642\u064a\u062f \u0648\u0636\u0639 \u0645\u0627\u0644\u0627\u064b \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062f\u0631\u062c. \u0648\u0647\u0648 \u0628\u064a\u0639\u0629 \u0648\u0627\u062d\u062f\u0629 \u0628\u0645\u0639\u0646\u0649 \u0623\u0646 \u0627\u0644\u0628\u064a\u0639 \u0647\u0648 \u0645\u0627 \u0648\u0636\u0639\u0647 \u0641\u0642\u0637\u061b \u0647\u0630\u0647 \u0627\u0644\u0648\u062d\u062f\u0629 \u062a\u0633\u062c\u0651\u0644 \u0642\u064a\u0648\u062f\u0627\u064b \u0648\u0644\u0627 \u062a\u0639\u0631\u0641 \u0627\u0644\u0628\u064a\u0639.",
    "catalog.title": "الكتالوج والتسعير",
    "catalog.lead": "ما هو معروض للبيع، وبكم، وما الذي يخصمه. لا يوجد رقم هنا هو «السعر»: فاستخراج السعر هو عملية البيع نفسها، لأنه يستهلك القسيمة التي يطبّقها. هذه هي السطور المكتوبة.",
    "catalog.notYet": "ما لا تفعله هذه الشاشة بعد",
    "catalog.noStockTitle": "لا مخزون، لا لكل نادٍ ولا إطلاقاً",
    "catalog.noStockWhy": "يرسم ADM-POS-01 عموداً لكل نادٍ ويُعتِم المنتج فقط عند نقطة البيع التي ينقصه فيها فعلاً. وMOD-016 هي الكتالوج والسعر؛ لا جرد فيها، فلا شيء يُعدّ ولا شيء يُعتَّم.",
    "catalog.noTaxTitle": "لا رقم ضريبي على المنتج",
    "catalog.noTaxWhy": "تُسمّي فئة الضريبة نظاماً ولا تحمل نسبة — وهي سابقة MOD-015، حيث يأخذ إصدار الفاتورة نسبةً بدل أن يخترعها. وعمودٌ هنا سيكون رقماً لم يحسبه أحد.",
    "catalog.noThresholdTitle": "لا حدود للخصم",
    "catalog.noThresholdWhy": "يضبط ADM-POS-03 رقماً واحداً تفرضه كل نقطة بيع — وفوقه يجب حضور مدير. وتملك MOD-016 آلية الموافقة لكل حملة ولا حدّ على مستوى المستأجر، فلا شيء يُعرض ولا شيء يُضبط.",
