    "catalog.notThePrice": "السطر الذي ضمن نافذته ليس السعر المستخرج. ثلاثة أمور تحدّد كلفة البيع — نافذة هذا السطر، وفعالية دفتره، وفوز ذلك الدفتر بالأولوية على كل دفتر آخر يطابق قناة البيع والشريحة والعلامة والموقع والتاريخ والعملة. هذا يجيب عن الأول.",
    "catalog.sellable": "لهذا المنتج سعر ساري ويمكن بيعه.",
    "catalog.noLivePrice": "منشور بلا سعر ساري. يتحقّق النشر من وجود سعر ولا يُعاد التحقّق بعده، فالسعر الذي حلّ محله سعر آخر، أو دفتر لم يفعّله أحد، يتركان منتجًا لا تستطيع نقطة البيع بيعه.",
