    "privacy.lead": "ما تعالجه هذه المنشأة، وما تحتفظ به، وما تحفظه، ومن طلب بياناته. الكتلة الأولى ليست عن هذه المنشأة أصلًا: إنها ما يستطيع هذا البناء محوه وما لا يستطيع.",
