    "notify.reason.quietHours": "وصلت داخل ساعات هدوء العضو، فتنتظر ولا تُسقط",
    "notify.reason.capReached": "بلغ الحد اليومي، فتُحتجز ضمن تجميعة",
    "notify.reason.criticalBypass": "أُرسلت بتجاوز موثّق يكلّف صلاحية مرفوعة",
    "notify.reason.channelOff": "القناة معطّلة ولا بديل لها",
    "notify.reason.noFallbackTemplate": "لا قالب للقناة البديلة، فلم يُكتب لها شيء",
    "notify.lead": "ما تستطيع هذه المنشأة قوله، وما قرّرت قوله، ومن لا يجوز أن تقول له شيئًا. لا يظهر نص رسالة ولا عنوان في هذه الصفحة: مسار القائمة لا يحمل النص عمدًا، والجداول تحتفظ ببصمة العنوان لا بالعنوان.",
    "notify.nothingSends": "لا شيء يُرسل في هذا البناء. لا مزوّد ولا بريد صادر ولا طلب خارجي: تُنشأ الرسالة ويطالب بها ما سيتولى الإرسال، ولا شيء يتولاه. عدد المنتظِرة أدناه هو غياب المُرسِل، لا قائمة انتظار يجب تفريغها.",
    "notify.notYet": "ما لا تفعله هذه الشاشة بعد",
    "notify.noMatrixTitle": "لا مصفوفة قنوات لكل حدث",
    "notify.noMatrixWhy": "يرسم ADM-COM-04 صفاً لكل حدث وعموداً لكل قناة، ويقول إن الإعدادات الافتراضية هادئة عمداً. وتفضيلات MOD-013 لكل مستلم وفئة وقناة — فلا إعداد افتراضي على مستوى المستأجر يُعرض أو يُضبط، ومصفوفةٌ هنا ستكون اختراعاً له.",
    "notify.noPairTitle": "يمكن نشر قالب بلغة واحدة",
    "notify.noPairWhy": "ADM-COM-02 صريح: «كل قالب موجود كزوج. والقالب بلغة واحدة لا يمكن نشره.» وتفهرس MOD-013 النسخة على المفتاح والقناة واللغة ولا تفرض الاقتران، ويسمّي سجلّها الثغرة: لا سلسلة احتياط للتوطين، لأن إرسال الإنجليزية بهدوء لمن طلب العربية أسوأ من الرفض. وإغلاق هذا يحتاج القيد، لا عموداً.",
    "notify.authored": "الرسائل المُنشأة",
    "notify.authoredLead": "كل طلب يُنشأ حتى لو مُنع، لأن الطلب الذي يختفي لا يستطيع أحد تفسيره حين يسأل العضو لماذا لم يصله شيء.",
    "notify.noneAuthored": "لم يُطلب شيء.",
