    "notify.noDispatcher": "لا يوجد مُرسِل هنا",
    "notify.noReason": "لم يُسجَّل سبب",
    "notify.noBodyHere": "النص المُصاغ ليس في هذه القائمة ولا تطلبه هذه الصفحة. القائمة التي تحمل النص تكون مسار قراءة لكل ما قالته هذه المنشأة لأي أحد، بصلاحية واحدة.",
    "notify.suppressions": "العناوين الممنوعة",
    "notify.suppressionsLead": "لا يُرفع إلا إلغاء الاشتراك. الارتداد أو الشكوى حكم القناة على قابلية التسليم، ورفعه يعني اختيار مواصلة الإرسال إلى عنوان رفضك — ما يضرّ بفرصة وصول كل رسالة أخرى، بما فيها ما لم يلغِ أحد اشتراكه فيه.",
