    "notify.categoryDecides": "القالب يعلن الفئة ولا يتجاوزها أي حقل في الطلب. الفئة تقرّر إن كان سجل الموافقة مطلوبًا قبل طلب الرسالة أصلًا، وإن كان إلغاء الاشتراك يوقفها — فتبقى المنشأة قادرة دومًا على إبلاغ أحدهم بفشل دفعته.",
    "notify.digests": "نوافذ التجميع",
    "notify.digestsLead": "حد التكرار يجمّع ولا يُسقط، وهذا ما يجعل ضبط الحد منخفضًا آمنًا. لا شيء يصوغ الدفعة في رسالة واحدة ولا شيء يكنس النوافذ المفتوحة.",
    "notify.noDigests": "لا توجد نافذة تجميع مفتوحة.",
