    "integrations.obligationsMissing": "يحمل حركة دون الالتزامات المكتوبة:",
    "integrations.obligationsNote": "التثبيت الحرج الحيّ يحتاج بديلًا وإجراء تسوية وخطة خروج مكتوبة قبل أن يحمل أي حركة. تُفحص عند التفعيل ولا يُعاد فحصها، لذا تعيد هذه اللوحة الفحص عند كل قراءة — ثلاث سلاسل فارغة محت الثلاثة مرّةً من تثبيت حيّ بالصلاحية نفسها التي كتبتها.",
    "integrations.connections": "الاتصالات",
    "integrations.connectionsLead": "ما يجوز لطرف ثالث الوصول إليه، وإلى متى. توسيع النطاق إذن جديد لا تعديل، فالمنحة لا تقبل التحديث: التدوير سطر جديد يحلّ محل القديم.",
