    "integrations.scopesNote": "إلغاء التثبيت يُلغي كل اتصال في المعاملة نفسها، لأن إلغاءً يترك اتصالًا مأذونًا يعني منشأة تظن أن طرفًا ثالثًا لم يعد لديه وصول وهو لديه.",
    "integrations.credentials": "إشارات بيانات الاعتماد",
    "integrations.credentialsLead": "إشارة لا سر. لا يوجد هنا عمود يمكن تخزين مفتاح فيه، ولا نوع حقل سرّي في دليل التعريفات للسبب نفسه.",
