    "integrations.noVault": "الخزنة التي تشير إليها غير موجودة في هذا البناء. وهي نفسها التي تنتظرها بذور TOTP والمحو التشفيري وتواقيع الويب هوك الواردة وشهادات الأجهزة — ثغرة واحدة لا أربع.",
    "integrations.runs": "عمليات التشغيل",
    "integrations.runsLead": "التشغيل سجل بأن أحدهم بدأه وأبلغ بنتيجة. لا شيء هنا اتصل بمزوّد.",
