    "integrations.cursorsLead": "موضع المؤشر معتم ولا يُرتَّب أبدًا: قد يكون موضع المزوّد طابعًا زمنيًا أو رمزًا أو رقمًا تسلسليًا، فالمقارنة تجري على وقت الرصد.",
    "integrations.noCursors": "لا يوجد مؤشر.",
    "integrations.observedAt": "رُصد",
    "integrations.conflictNote": "سياسة التعارض تُسجَّل لكل مؤشر ولا يقرأها أحد: لا شيء يقارن سجل المزوّد بسجل محلي، فالسياسة تُقرَّر ولا تُطبَّق.",
    "nav.account": "حسابك",
    "account.title": "حسابك",
    "passkey.heading": "\u0645\u0641\u0627\u062a\u064a\u062d \u0627\u0644\u0645\u0631\u0648\u0631",
    "passkey.lead": "\u064a\u0633\u062c\u0651\u0644 \u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0645\u0631\u0648\u0631 \u062f\u062e\u0648\u0644\u0643 \u0628\u0628\u0635\u0645\u062a\u0643 \u0623\u0648 \u0648\u062c\u0647\u0643 \u0623\u0648 \u0631\u0642\u0645\u0643 \u0627\u0644\u0633\u0631\u064a \u0627\u0644\u0630\u064a \u064a\u0637\u0644\u0628\u0647 \u062c\u0647\u0627\u0632\u0643 \u0623\u0635\u0644\u0627\u064b. \u0648\u0647\u0648 \u0627\u0644\u0639\u0627\u0645\u0644 \u0627\u0644\u062b\u0627\u0646\u064a \u0627\u0644\u0648\u062d\u064a\u062f \u0647\u0646\u0627 \u0627\u0644\u0630\u064a \u0644\u064a\u0633 \u0631\u0645\u0632 \u0627\u0633\u062a\u0631\u062f\u0627\u062f\u060c \u0648\u0627\u0644\u0648\u062d\u064a\u062f \u0627\u0644\u0630\u064a \u064a\u0628\u0644\u063a \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u062a\u0648\u0643\u064a\u062f \u2014 \u0648\u0647\u0648 \u0645\u0627 \u064a\u062d\u062a\u0627\u062c\u0647 \u0623\u064a \u0625\u062c\u0631\u0627\u0621 \u0645\u0645\u064a\u0651\u0632.",
    "passkey.none": "\u0644\u0627 \u0645\u0641\u062a\u0627\u062d \u0645\u0631\u0648\u0631 \u0645\u0633\u062c\u0651\u0644 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628\u060c \u0641\u0631\u0645\u0632 \u0627\u0644\u0627\u0633\u062a\u0631\u062f\u0627\u062f \u0647\u0648 \u0639\u0627\u0645\u0644\u0643 \u0627\u0644\u062b\u0627\u0646\u064a \u0627\u0644\u0648\u062d\u064a\u062f. \u0648\u0643\u0644 \u0631\u0641\u0639 \u0644\u0644\u062c\u0644\u0633\u0629 \u064a\u0633\u062a\u0647\u0644\u0643 \u0648\u0627\u062d\u062f\u0627\u064b \u0645\u0646\u0647\u0627.",
    "passkey.add": "\u0623\u0636\u0641 \u0645\u0641\u062a\u0627\u062d \u0645\u0631\u0648\u0631",
    "passkey.adding": "\u0641\u064a \u0627\u0646\u062a\u0638\u0627\u0631 \u062c\u0647\u0627\u0632\u0643",
    "passkey.label": "\u0628\u0645\u0627\u0630\u0627 \u0646\u0633\u0645\u0651\u064a\u0647",
    "passkey.labelHint": "\u0644\u062a\u0645\u064a\u0651\u0632\u0647 \u0639\u0646 \u0627\u0644\u062a\u0627\u0644\u064a. \u0648\u0627\u0633\u0645 \u062c\u0647\u0627\u0632\u0643 \u062c\u0648\u0627\u0628 \u062c\u064a\u0651\u062f.",
    "passkey.added": "\u0633\u064f\u062c\u0651\u0644 \u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0645\u0631\u0648\u0631 \u0648\u064a\u0633\u062a\u0637\u064a\u0639 \u062a\u0633\u062c\u064a\u0644 \u062f\u062e\u0648\u0644\u0643.",
    "passkey.withdraw": "\u0627\u0633\u062d\u0628\u0647",
    "passkey.withdrawn": "\u0644\u0645 \u064a\u0639\u062f \u0647\u0630\u0627 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u064a\u0633\u062c\u0651\u0644 \u062f\u062e\u0648\u0644 \u0623\u062d\u062f. \u0648\u0627\u0644\u062c\u0644\u0633\u0629 \u0627\u0644\u062a\u064a \u062a\u0642\u0631\u0623 \u0641\u064a\u0647\u0627 \u0647\u0630\u0627 \u0644\u0645 \u062a\u064f\u0645\u064e\u0633.",
    "passkey.ceremonyFailed": "\u0644\u0645 \u064a\u064f\u0643\u0645\u0644 \u062c\u0647\u0627\u0632\u0643 \u0630\u0644\u0643. \u0648\u0644\u0645 \u064a\u064f\u062d\u0641\u0638 \u0634\u064a\u0621 \u2014 \u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0623\u0648 \u0627\u0633\u062a\u062e\u062f\u0645 \u062c\u0647\u0627\u0632\u0627\u064b \u0622\u062e\u0631.",
    "passkey.unsupported": "\u064a\u0633\u062a\u0637\u064a\u0639 \u0647\u0630\u0627 \u0627\u0644\u0645\u062a\u0635\u0641\u0651\u062d \u0625\u0646\u0634\u0627\u0621 \u0645\u0641\u062a\u0627\u062d \u0645\u0631\u0648\u0631 \u0648\u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u062a\u0633\u0644\u064a\u0645 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0639\u0627\u0645 \u0628\u0635\u0648\u0631\u0629 \u064a\u062a\u062d\u0642\u0651\u0642 \u0645\u0646\u0647\u0627 \u0647\u0630\u0627 \u0627\u0644\u0625\u0635\u062f\u0627\u0631\u060c \u0641\u062a\u0633\u062c\u064a\u0644\u0647 \u0647\u0646\u0627 \u064a\u0639\u0646\u064a \u062a\u062e\u0632\u064a\u0646 \u0628\u064a\u0627\u0646\u0627\u062a \u0644\u0627 \u062a\u0633\u062a\u0637\u064a\u0639 \u062a\u0633\u062c\u064a\u0644 \u062f\u062e\u0648\u0644\u0643 \u0623\u0628\u062f\u0627\u064b. \u0623\u0645\u0627 \u0625\u0635\u062f\u0627\u0631 \u062d\u062f\u064a\u062b \u0645\u0646 Chrome \u0623\u0648 Safari \u0623\u0648 Edge \u0623\u0648 Firefox \u0641\u064a\u0633\u062a\u0637\u064a\u0639.",
    "passkey.browserCannot": "\u0644\u0627 \u064a\u062f\u0639\u0645 \u0647\u0630\u0627 \u0627\u0644\u0645\u062a\u0635\u0641\u0651\u062d \u0645\u0641\u0627\u062a\u064a\u062d \u0627\u0644\u0645\u0631\u0648\u0631\u060c \u0641\u0644\u0627 \u0634\u064a\u0621 \u0646\u0639\u0631\u0636\u0647 \u0647\u0646\u0627.",
