    "passkey.state.in_use": "\u0642\u064a\u062f \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645",
    "passkey.state.withdrawn": "\u0645\u0633\u062d\u0648\u0628",
    "passkey.created": "\u0623\u064f\u0636\u064a\u0641",
    "passkey.lastUsed": "\u0622\u062e\u0631 \u0627\u0633\u062a\u062e\u062f\u0627\u0645",
    "passkey.neverUsed": "\u0644\u0645 \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0628\u0639\u062f",
    "passkey.deviceBound": "\u064a\u0628\u0642\u0649 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632",
    "passkey.backedUp": "يمكن مزامنته إلى سلسلة مفاتيح",
    "passkey.whyBound": "مفتاح المرور الذي لا يستطيع مغادرة موثّقه يبلغ مستوى التوكيد 3، والذي يمكن مزامنته إلى سلسلة مفاتيح يبلغ 2، لأن المفتاح القادر على مغادرة جهازه عامل قويّ وليس مرتبطاً بعتاد. والموثّق هو من يقرّر أيّهما عند إنشاء البيانة، ويقول ذلك في كل توقيع يصدره.",
    "passkey.signIn": "\u0627\u0633\u062a\u062e\u062f\u0645 \u0645\u0641\u062a\u0627\u062d \u0645\u0631\u0648\u0631",
    "passkey.signingIn": "\u0641\u064a \u0627\u0646\u062a\u0638\u0627\u0631 \u062c\u0647\u0627\u0632\u0643",
    "passkey.needIdentifier": "\u0627\u0643\u062a\u0628 \u0628\u0631\u064a\u062f\u0643 \u0623\u0648 \u0647\u0627\u062a\u0641\u0643 \u0623\u0648\u0644\u0627\u064b\u060c \u0644\u0646\u0639\u0631\u0641 \u0645\u0641\u062a\u0627\u062d \u0645\u064e\u0646 \u0646\u0637\u0644\u0628.",
    "passkey.signInFailed": "\u0644\u0645 \u064a\u0633\u062c\u0651\u0644 \u0630\u0644\u0643 \u062f\u062e\u0648\u0644\u0643. \u0642\u062f \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0645\u0633\u062d\u0648\u0628\u0627\u064b\u060c \u0623\u0648 \u0642\u062f \u064a\u0643\u0648\u0646 \u0644\u062d\u0633\u0627\u0628 \u0622\u062e\u0631.",
    "passkey.notYetVerified": "\u0645\u0627 \u0644\u0627 \u064a\u062a\u062d\u0642\u0651\u0642 \u0645\u0646\u0647 \u0647\u0630\u0627 \u0627\u0644\u0625\u0635\u062f\u0627\u0631 \u0647\u0648 \u0637\u0631\u0627\u0632 \u0627\u0644\u0645\u0648\u062b\u0651\u0642 \u0627\u0644\u0630\u064a \u062c\u0627\u0621 \u0645\u0646\u0647 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u2014 \u0641\u0630\u0644\u0643 \u064a\u062d\u062a\u0627\u062c \u062e\u062f\u0645\u0629 \u0628\u064a\u0627\u0646\u0627\u062a \u0648\u0635\u0641\u064a\u0629 \u0644\u0627 \u064a\u0645\u0644\u0643\u0647\u0627. \u0623\u0645\u0651\u0627 \u0645\u0627 \u064a\u062a\u062d\u0642\u0651\u0642 \u0645\u0646\u0647 \u0641\u0647\u0648 \u0627\u0644\u062a\u0648\u0642\u064a\u0639\u060c \u0648\u0647\u0648 \u0645\u0627 \u064a\u062b\u0628\u062a \u0623\u0646 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0645\u0641\u062a\u0627\u062d\u0643.",
    "account.lead": "هذه الجلسة، والأجهزة التي جاءت منها، والجلسات الأخرى المفتوحة على هذا الحساب، وما يقوله سجل الدخول. كل ما هنا يخصّك: هذه المسارات ترفض أي موضوع غير موضوعك، ولهذا لا يطلب أيٌّ منها صلاحية.",
    "account.thisSession": "هذه الجلسة",
    "account.assurance": "مستوى التحقّق",
    "account.steppedUp": "مرفوع، فالإجراءات المالية متاحة",
    "account.passwordOnly": "كلمة مرور فقط، فالإجراءات المالية ستطلب عاملًا ثانيًا",
    "account.hardwareLevel": "\u0645\u0641\u062a\u0627\u062d \u0645\u0631\u0648\u0631 \u0639\u0644\u0649 \u0645\u0648\u062b\u0651\u0642 \u0639\u062a\u0627\u062f\u064a\u060c \u0648\u0647\u0648 \u0623\u0639\u0644\u0649 \u062a\u0648\u0643\u064a\u062f \u064a\u0645\u0644\u0643\u0647 \u0647\u0630\u0627 \u0627\u0644\u0645\u0646\u062a\u062c \u2014 \u0643\u0644 \u0627\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0645\u062a\u0627\u062d\u0629\u060c \u0648\u0645\u0646\u0647\u0627 \u0645\u0627 \u0644\u0627 \u062a\u0628\u0644\u063a\u0647 \u0623\u064a \u0628\u064a\u0627\u0646\u0627\u062a \u0623\u062e\u0631\u0649",
    "account.shortestWindow": "\u0623\u0642\u0648\u0649 \u0628\u064a\u0627\u0646\u0627\u062a \u062a\u0641\u062a\u062d \u0623\u0642\u0635\u0631 \u0646\u0627\u0641\u0630\u0629: \u062e\u0645\u0633 \u0639\u0634\u0631\u0629 \u062f\u0642\u064a\u0642\u0629\u060c \u0648\u062a\u062f\u0648\u064a\u0631\u0647\u0627 \u0644\u0627 \u064a\u0645\u062f\u0651\u062f\u0647\u0627",
    "account.provedWith": "أُثبت بـ",
    "account.expires": "تنتهي",
    "account.shortWindow": "الجلسة المرفوعة تأخذ نافذة قصيرة، وتدويرها لا يمدّدها",
    "account.longWindow": "جلسة كلمة المرور تأخذ النافذة الطويلة",
    "account.recoveryCodes": "رموز الاسترداد",
    "account.recoveryLead": "رمز الاسترداد هو العامل الثاني الذي يستطيع رفع الجلسة استخدامه، وكل رمز يُستخدم مرة واحدة — ورفع الجلسة يستهلك واحداً، فالإصدار من جديد هو ما يمنع نفادها. ولا يوجد هنا رمز من تطبيق موثّق، لعدم وجود مكان آمن لحفظ سرّه.",
    "account.recoveryAndPasskey": "ولديك أيضاً مفتاح مرور، والدخول به لا يستهلك شيئاً — فنفاد الرموز ليس طريقاً للخروج من حسابك.",
    "account.recoveryIsTheOnlyWayBack": "ليس لديك مفتاح مرور، فهذه الرموز هي العامل الثاني الوحيد على حسابك — والدفعة التي تنفد تدفع برمزها الأخير ثمن رفع الجلسة التي تصدر الدفعة التالية. وتسجيل مفتاح مرور أدناه هو المخرج من ذلك، وهو لا يستهلك شيئاً.",
    "account.codesNeedStepUp": "إصدار الرموز يحتاج جلسة مرفوعة، لأن ملف الارتباط وحده يجب ألّا يكفي للاستيلاء على حساب نهائيًا. ارفع الجلسة ثم عُد.",
    "account.issueCodes": "أصدر دفعة جديدة",
