    "rota.pickResourceInLink": "\u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629 \u062a\u0642\u0631\u0623 \u0627\u0644\u062c\u062f\u0648\u0644 \u0648\u0644\u0627 \u062a\u0633\u0631\u062f \u0627\u0644\u0645\u0648\u0627\u0631\u062f\u060c \u0641\u0627\u0641\u062a\u062d\u0647 \u0645\u0646 \u0631\u0627\u0628\u0637 \u064a\u0633\u0645\u064a \u0645\u0648\u0631\u062f\u0627\u064b.",
