    "reports.sourceUnattributed": "\u0645\u064f\u0635\u062f\u0631\u0629 \u064a\u062f\u0648\u064a\u0627\u064b",
    "reports.unattributedWhy": "\u0633\u0637\u0631 \u0641\u0627\u062a\u0648\u0631\u0629 \u0628\u0644\u0627 \u0646\u0633\u062e\u0629 \u0645\u0646 \u0627\u0644\u0643\u062a\u0627\u0644\u0648\u062c \u0644\u0627 \u064a\u0645\u0643\u0646 \u0646\u0633\u0628\u062a\u0647 \u0625\u0644\u0649 \u062c\u0632\u0621 \u0645\u0646 \u0627\u0644\u0639\u0645\u0644. \u0647\u0648 \u0635\u0641 \u0645\u0633\u062a\u0642\u0644 \u0628\u062f\u0644 \u0623\u0646 \u064a\u064f\u0633\u0642\u0637\u060c \u062d\u062a\u0649 \u062a\u062c\u0645\u0639 \u0627\u0644\u0645\u0635\u0627\u062f\u0631 \u0625\u0644\u0649 \u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u0645\u0641\u0648\u062a\u0631.",
    "reports.entityNotClub": "\u064a\u0641\u0635\u0651\u0644 \u0627\u0644\u062a\u0635\u0645\u064a\u0645 \u0647\u0630\u0627 \u062d\u0633\u0628 \u0627\u0644\u0646\u0627\u062f\u064a. \u0627\u0644\u0645\u0627\u0644 \u0647\u0646\u0627 \u064a\u062d\u0645\u0644 \u0643\u064a\u0627\u0646\u0627\u064b \u0642\u0627\u0646\u0648\u0646\u064a\u0627\u064b\u060c \u0648\u0627\u0644\u062a\u0633\u0644\u0633\u0644 \u064a\u0636\u0639 \u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a \u0648\u0627\u0644\u0645\u0648\u0627\u0642\u0639 \u062a\u062d\u062a\u0647 \u2014 \u0641\u0639\u062f\u0629 \u0646\u0648\u0627\u062f\u064d \u062a\u062d\u062a \u0643\u064a\u0627\u0646 \u0648\u0627\u062d\u062f \u0639\u0645\u0648\u062f \u0648\u0627\u062d\u062f.",
