    "wallet.originWhy": "\u0643\u0644 \u0642\u064a\u062f \u064a\u0633\u0645\u0651\u064a \u0645\u0635\u062f\u0631\u0647 \u2014 \u062d\u0635\u0629 \u0623\u064f\u0644\u063a\u064a\u062a\u060c \u062f\u0641\u0639\u0629 \u0632\u0627\u0626\u062f\u0629\u060c \u0644\u0641\u062a\u0629 \u062d\u0633\u0646 \u0646\u064a\u0629 \u2014 \u0644\u0623\u0646 \u0631\u0635\u064a\u062f\u0627\u064b \u0628\u0644\u0627 \u062a\u0641\u0633\u064a\u0631 \u0644\u0627 \u064a\u064f\u0645\u064a\u0651\u0632 \u0639\u0646 \u062e\u0637\u0623. \u0648\u0627\u0644\u0642\u064a\u062f \u0627\u0644\u0645\u0646\u062a\u0647\u064a \u064a\u064f\u0639\u0631\u0636 \u0648\u0644\u0627 \u064a\u064f\u062d\u0630\u0641: \u00ab\u0623\u064a\u0646 \u0630\u0647\u0628 \u0631\u0635\u064a\u062f\u064a\u061f\u00bb \u0647\u0648 \u0627\u0644\u0633\u0624\u0627\u0644 \u0627\u0644\u0630\u064a \u064a\u0637\u0631\u062d\u0647 \u0627\u0644\u0639\u0636\u0648.",
