    "staff.restricted": "ليس من حقّك",
    "staff.emptyFirstUse": "لا أحد لديه سجلّ موظف في هذا المستأجر بعد. سجلّ الموظف يُكتب على شخص، فالأشخاص أولاً.",
    "staff.seenIsWhy": "**الصلاحية زوج من الحقائق، لا تاريخ.** التصميم يقولها كذلك: «آخر ظهور» موجود ليكون الموظف الذي ترك العمل وما يزال حسابه حيّاً مرئيّاً لا مُكتشفاً. والتاريخ وحده لا يقول ذلك، لأن حساباً لم يُستخدم سنة ما يزال يعمل، وحساباً استُخدم هذا الصباح قد يكون أُلغي بعده.",
    "staff.notYet": "ما لا تستطيعه هذه الشاشة",
    "staff.inviteTitle": "دعوة شخص",
    "staff.inviteWhy": "لا توجد دعوة في هذا البناء إطلاقاً: لا جدول، ولا رمز، ولا مهلة، ولا شيء يُرسل. فلا زرّ **دعوة** ولا شريحة ثالثة — شريحة تقول `مدعوّون · 0` تعني أن لا أحد دُعي، لا أن لا شيء يستطيع دعوة أحد.",
    "staff.certTitle": "الشهادات",
    "staff.certWhy": "لا جدول هنا يحمل شهادة مدرّب أو تاريخ انتهائها، فتحذير الثلاثين يوماً في التصميم لا يجد ما يقرأه. وما يُرسم مكانه اكتشافٌ خلفه بيانات حقيقية، وهو الاكتشاف الذي تسمّيه حاشية التصميم نفسها.",
    "staff.scopeTitle": "أن يرى مدير النادي فريق ناديه وحده",
    "staff.scopeWhy": "ليس صحيحاً هنا. كل تحقّق من صلاحية في هذا البناء يُحسم على نطاق المستأجر كاملاً، فالدور المحدود بعلامة أو بموقع لا يغطّي شيئاً، ولا شيء يستنتج نادي القارئ نفسه. التصفية أعلاه تُضيّق القائمة ولا تحدّ من يقرأها.",
    "staff.writesTitle": "تغيير أي شيء",
    "staff.writesWhy": "إنشاء سجلّ موظف وإنهاء العمل مبنيّان على الخادم وليس لأيٍّ منهما نموذج هنا؛ ومنح دور أو إلغاؤه صلاحية مالية مُصعَّدة. وزرٌّ يُجيب بـ403 أسوأ من غيابه.",
