    "recovery.noTemplate": "لا قالب منشور لـ{key}، فهذه المرحلة لن ترسل شيئاً. والإشعار الذي لم يكتبه أحد ليس إشعاراً.",
    "recovery.placeholders": "قيم يزوّدها المُرسِل:",
    "recovery.serviceMessage": "هذا هو القالب المنشور لهذه المرحلة، ويُعرض كما كُتب لا مُركَّباً — فالقيم أدناه يزوّدها المُرسِل، وهذا البناء لا يملك رابط دفع ليزوّد إحداها. وتُرسَل بلغة العضو المختارة، وهي قالب منشور مختلف لا ترجمة لهذا — ولا سلسلة احتياط، فاللغة التي لا قالب لها تُرفض بدل أن يُجاب عنها بلغة أخرى. **والفئة أعلاه هي ما يجعل هذه رسالة خدمة**: لا يجوز كتم غير `coaching` و`marketing` بتفضيل المستلم، بقيد CHECK على `ntf_preferences` لا بعُرف، فالعضو الذي سحب موافقته التسويقية يتلقّاها رغم ذلك. والتمييز يفرضه النظام لا يُترك للمُرسِل.",
    "recovery.notYet": "ما لا تستطيعه هذه الشاشة",
    "recovery.sendTitle": "إرسال الروابط",
    "recovery.sendWhy": "لا شيء في هذا البناء يُرسل. يكتب MOD-013 الإشعار ويسجّل ما أبلغ عنه المُرسِل؛ ولا مزوّد ولا SMTP ولا طلب صادر، فكل رسالة تبقى عند `requested`. فزر الإرسال الجماعي في التصميم لا كاتب خلفه، ومربّعات الاختيار في الصفوف تختار لإجراء غير موجود — فلا يُرسم أيٌّ منهما.",
    "recovery.linkTitle": "رابط الدفع",
    "recovery.linkWhy": "`veyro.link/p/8k2m` رابط أحادي الاستخدام خاص بعضو بعينه، ولا جدول في هذا البناء يحمل واحداً. ولهذا تُظهر المعاينة عنصر القالب النائب لا عنواناً: فرابط مُختلَق في معاينة رسالة يُقرأ كرابط يعمل.",
    "recovery.cardTitle": "البطاقة",
    "recovery.cardWhy": "لا علامة بطاقة ولا آخر أربعة أرقام في أي موضع من هذا البناء. تُبقي الفقرة 1597 بيانات البطاقات خارج Veyro، فـ`payment_method_ref` رمز يحتفظ به المزوّد، ونوع الأداة هو كل ما يستطيع الصف قوله.",
    "recovery.consentTitle": "من سحب موافقته التسويقية",
    "recovery.consentWhy": "التصميم يَعُدّهم. وهذه الصفحة لا تفعل: العدّ يحتاج قراءة موافقة لكل دافع، أي طلباً لكل صف، و`privacy.consent.read` صلاحية منفصلة عن تلك التي تقف خلف هذه الشاشة. فالقاعدة التي يوضّحها ذلك العدد مرسومة أعلاه بدلاً منه، من فئة القالب نفسها، لأن تلك القاعدة هي الجزء الذي يتصرّف المُرسِل بناءً عليه.",
