    "tasks.sourceAlwaysNamed": "ثلاثة مصادر: أسندها شخص، أو أنشأتها أتمتة، أو اقترحتها فيرو. والمصدر مذكور دائماً — فالمهمة التي لا يُعرف مصدرها تُهمَل.",
