    "tasks.gapAssignedBy": "يذكر سطر التصميم من أسند المهمة — «أسندتها رانيا». ولا شيء يسجّل ذلك: المهمة تحمل مُسنداً إليه ولا تحمل مُسنِداً، فإعادة توجيهها بلا عزو. «من يحمل ماذا» سؤال يُجاب هنا، و«من أعطاه إياه» لا.",
    "tasks.gapBatchMessage": "«أرسل 6 روابط دفع» يحتاج مزوّد رسائل. تؤلّف الوحدة MOD-013 الرسالة وتحتجزها وتسوّيها ولا ترسل شيئاً — فزرٌّ هنا يبلّغ عن عمل لم يحدث.",
    "tasks.gapReopen": "يقدّم التصميم «إعادة الفتح» على بند محلول. وإعادة الفتح بندٌ جديد يشير إلى هذا، ومرجعه ملك المنشأة — ولا شيء في هذا البناء يولّده، ونموذج يطلب من القارئ كتابة رقم بند هو طلبٌ بأن يؤدي عمل المنتج.",
    "tasks.gapSideSheet": "يرسم التصميم هذا لوحاً جانبياً فوق مركز القيادة، يُغلق عائداً إلى الصف الذي فُتح منه. وطابور مركز القيادة هنا محسوبٌ حياً من التحصيل والتوظيف والأبواب لا مقيّداً كبنود، فلا صفّ يفتح هذا وهو صفحة بذاتها.",
    "tasks.gapUndo": "يضع التصميم تراجعاً مدته ثلاثون ثانية على الحل. والحل هنا أحادي الاتجاه بمُشغِّل في قاعدة البيانات، فلا شيء يُتراجع به — وهو أيضاً ما يجعل قائمة المحلول سجلاً لا حالة.",
    "tasks.gapScope": "يحصر التصميم الاستثناء في نادي القارئ نفسه. وكل تحقّق صلاحية في هذا البناء يُحسم على مستوى المنشأة، فمدير النادي يرى كل الطوابير.",
    "tasks.gapAffectedNames": "يطبع التصميم سبباً ومبلغاً أمام كل سجل — «انتهت البطاقة · 55.00» — ولا شيء يربط السجل المتأثر بالقيد الذي يتعلق به. والاسم بجانب كل سجل مؤلّف عبر الصلاحية التي تحرس سجل العضو، فيُحجب حيث تُحجب هي.",
